begin;
update public.questions set subject = 'History', topic = 'Modern', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of associations and the sections of society or causes they chiefly represented:', body_hi = 'निम्नलिखित संगठनों और उनके द्वारा मुख्य रूप से प्रतिनिधित्व किए गए वर्गों या उद्देश्यों के युग्मों पर विचार कीजिए:', explanation = 'Three pairs are correct. The British Indian Association of Calcutta spoke mainly for the zamindars, while Dadabhai Naoroji organised the East India Association in London to put India''s case before British opinion. The Bombay Presidency Association of 1885 was the work of the city''s lawyers and other professionals. Pair 3 is wrong: the Madras Mahajan Sabha was founded by educated Indians of Madras such as M. Viraraghavachari and P. Anandacharlu. The shift from landlords'' bodies to middle-class associations in the 1870s and 1880s prepared the ground for the Congress.', explanation_hi = 'तीन युग्म सही हैं। कलकत्ता की ब्रिटिश इंडियन एसोसिएशन मुख्यतः ज़मींदारों की बात करती थी, जबकि दादाभाई नौरोजी ने भारत का पक्ष ब्रिटिश जनमत के सामने रखने के लिए लंदन में ईस्ट इंडिया एसोसिएशन संगठित की। 1885 की बॉम्बे प्रेसिडेंसी एसोसिएशन नगर के वकीलों और अन्य पेशेवरों का काम थी। युग्म 3 गलत है: मद्रास महाजन सभा की स्थापना मद्रास के शिक्षित भारतीयों, जैसे एम. वीरराघवाचारी और पी. आनंदाचार्लु, ने की थी। 1870 और 1880 के दशकों में ज़मींदारों के निकायों से मध्यवर्गीय संगठनों की ओर यह बदलाव कांग्रेस की भूमिका तैयार करता है।', concept_group_id = 'modern-pre-congress-associations-pairs', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"list_1": ["1. British Indian Association (1851)", "2. East India Association (1866)", "3. Madras Mahajan Sabha (1884)", "4. Bombay Presidency Association (1885)"], "list_1_hi": ["1. ब्रिटिश इंडियन एसोसिएशन (1851)", "2. ईस्ट इंडिया एसोसिएशन (1866)", "3. मद्रास महाजन सभा (1884)", "4. बॉम्बे प्रेसिडेंसी एसोसिएशन (1885)"], "list_2": ["The zamindars of Bengal", "Informing British opinion in London about Indian grievances", "The European planters of south India", "The educated professionals of Bombay city"], "list_2_hi": ["बंगाल के ज़मींदार", "लंदन में ब्रिटिश जनमत को भारतीय शिकायतों से अवगत कराना", "दक्षिण भारत के यूरोपीय बागान मालिक", "बंबई नगर के शिक्षित पेशेवर"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-pre-congress-associations-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of uprisings and the grievances behind them:', body_hi = 'निम्नलिखित विद्रोहों और उनके पीछे की शिकायतों के युग्मों पर विचार कीजिए:', explanation = 'Three pairs are correct. The Paikas of Khurda, under Bakshi Jagabandhu, rose when the Company''s revenue policy took away the rent-free lands they held for military service. The Kols of Chota Nagpur rose against the outsiders -- moneylenders, traders and farmers of revenue -- who were taking over their land. The Pagal Panthis of Mymensingh in Bengal, under Tipu Shah, resisted the zamindars'' illegal cesses and high rents. Pair 4 is wrong: the Ahom nobles, led by Gomdhar Konwar, rose because the Company had not withdrawn from Assam after the First Anglo-Burmese War, as they had expected, and moved to absorb the kingdom.', explanation_hi = 'तीन युग्म सही हैं। खुर्दा के पाइक बख़्शी जगबंधु के नेतृत्व में तब उठे जब कंपनी की राजस्व नीति ने सैनिक सेवा के बदले मिली उनकी लगान-मुक्त भूमि छीन ली। छोटानागपुर के कोल उन बाहरी लोगों, यानी साहूकारों, व्यापारियों और राजस्व ठेकेदारों, के विरुद्ध उठे जो उनकी भूमि हथिया रहे थे। बंगाल के मैमनसिंह के पागल पंथियों ने टीपू शाह के नेतृत्व में ज़मींदारों के अवैध उपकरों और ऊँचे लगान का विरोध किया। युग्म 4 गलत है: अहोम सामंत गोमधर कोंवर के नेतृत्व में इसलिए उठे कि कंपनी प्रथम आंग्ल-बर्मा युद्ध के बाद, उनकी अपेक्षा के विपरीत, असम से नहीं हटी और राज्य को अपने में मिलाने लगी।', concept_group_id = 'modern-uprisings-regions-pairs', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"list_1": ["1. Paika rebellion (1817)", "2. Kol uprising (1831-32)", "3. Pagal Panthi movement", "4. Ahom revolt (1828)"], "list_1_hi": ["1. पाइक विद्रोह (1817)", "2. कोल विद्रोह (1831-32)", "3. पागल पंथी आंदोलन", "4. अहोम विद्रोह (1828)"], "list_2": ["Loss of the rent-free lands of Khurda''s traditional militia", "Transfer of tribal lands to outsiders", "Oppressive demands of zamindars on the peasants", "Forced cultivation of indigo"], "list_2_hi": ["खुर्दा की पारंपरिक सेना की लगान-मुक्त भूमि छिन जाना", "जनजातीय भूमि बाहरी लोगों के हाथ में जाना", "किसानों पर ज़मींदारों की दमनकारी माँगें", "नील की जबरन खेती"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-uprisings-regions-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of books and the central ideas they argued:', body_hi = 'निम्नलिखित पुस्तकों और उनमें प्रतिपादित केंद्रीय विचारों के युग्मों पर विचार कीजिए:', explanation = 'Only pairs 1 and 2 are correct. Gandhi''s Hind Swaraj argued that modern civilisation, not just British rule, was the real enemy, and that swaraj meant self-rule over oneself. Tilak, writing in Mandalay jail, read the Gita as a gospel of action (karma yoga) rather than of renunciation. Pair 3 reverses Gulamgiri: Jyotiba Phule compared the lower castes'' condition to slavery and attacked Brahminical domination. Pair 4 is also wrong: B.R. Ambedkar argued that caste could not be reformed while the authority of the shastras that sanctified it was accepted, and he rejected the varna order as well.', explanation_hi = 'केवल युग्म 1 और 2 सही हैं। गांधी के हिंद स्वराज का तर्क था कि असली शत्रु केवल ब्रिटिश शासन नहीं, आधुनिक सभ्यता है, और स्वराज का अर्थ स्वयं पर शासन है। तिलक ने मांडले जेल में लिखते हुए गीता को संन्यास नहीं, कर्म (कर्मयोग) के उपदेश के रूप में पढ़ा। युग्म 3 गुलामगिरी को उलट देता है: ज्योतिबा फुले ने निचली जातियों की स्थिति की तुलना दासता से की और ब्राह्मणवादी प्रभुत्व पर प्रहार किया। युग्म 4 भी गलत है: बी.आर. आंबेडकर का तर्क था कि जाति को पवित्र ठहराने वाले शास्त्रों का प्रामाण्य मानते हुए उसका सुधार नहीं हो सकता, और उन्होंने वर्ण व्यवस्था को भी अस्वीकार किया।', concept_group_id = 'modern-books-authors-pairs', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"list_1": ["1. Hind Swaraj (1909)", "2. Gita Rahasya", "3. Gulamgiri (1873)", "4. Annihilation of Caste (1936)"], "list_1_hi": ["1. हिंद स्वराज (1909)", "2. गीता रहस्य", "3. गुलामगिरी (1873)", "4. जाति का विनाश (1936)"], "list_2": ["A critique of modern Western civilisation", "The Gita as a call to selfless action", "Caste as a divinely ordained order to be preserved", "Reform of caste from within, keeping the varna order"], "list_2_hi": ["आधुनिक पश्चिमी सभ्यता की आलोचना", "गीता निष्काम कर्म का आह्वान", "जाति एक ईश्वर-प्रदत्त व्यवस्था जिसे बचाए रखना है", "वर्ण व्यवस्था बनाए रखते हुए भीतर से जाति का सुधार"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-books-authors-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'easy', body = 'Mahatma Gandhi called off the Non-Cooperation Movement in February 1922, soon after the violence at Chauri Chaura, mainly because:', body_hi = 'महात्मा गांधी ने चौरी चौरा की हिंसा के तुरंत बाद फ़रवरी 1922 में असहयोग आंदोलन वापस ले लिया, मुख्यतः इसलिए कि:', explanation = 'At Chauri Chaura in the United Provinces, on 5 February 1922, a crowd set fire to a police station and 22 policemen died. Gandhi concluded that the people were not yet ready for a non-violent mass struggle, and the Congress Working Committee suspended the movement at Bardoli a week later, though leaders such as Motilal Nehru and C.R. Das disagreed. Swaraj had not come in a year, and the Khilafat question lost its point only in 1924, when Turkey itself abolished the caliphate. Nor had the government made any concession: Gandhi himself was arrested in March 1922.', explanation_hi = 'संयुक्त प्रांत के चौरी चौरा में 5 फ़रवरी 1922 को भीड़ ने एक थाने में आग लगा दी और 22 पुलिसकर्मी मारे गए। गांधी इस निष्कर्ष पर पहुँचे कि लोग अभी अहिंसक जन-संघर्ष के लिए तैयार नहीं हैं, और एक सप्ताह बाद बारदोली में कांग्रेस कार्यसमिति ने आंदोलन स्थगित कर दिया, यद्यपि मोतीलाल नेहरू और सी.आर. दास जैसे नेता असहमत थे। एक वर्ष में स्वराज नहीं आया था, और ख़िलाफ़त का प्रश्न 1924 में ही अर्थहीन हुआ, जब तुर्की ने स्वयं ख़िलाफ़त समाप्त कर दी। सरकार ने कोई रियायत भी नहीं दी थी: मार्च 1922 में स्वयं गांधी गिरफ़्तार कर लिए गए।', concept_group_id = 'modern-non-cooperation-chauri-chaura', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "swaraj had been won within the one year he had promised", "body_hi": "उनके वादे के अनुसार एक वर्ष के भीतर स्वराज मिल गया था", "isCorrect": false}, {"id": "b", "body": "the Khilafat question had been settled in favour of Indian Muslims", "body_hi": "ख़िलाफ़त का प्रश्न भारतीय मुसलमानों के पक्ष में सुलझ गया था", "isCorrect": false}, {"id": "c", "body": "he felt the movement was losing its commitment to non-violence", "body_hi": "उन्हें लगा कि आंदोलन अहिंसा के प्रति अपनी प्रतिबद्धता खो रहा है", "isCorrect": true}, {"id": "d", "body": "the government had agreed to release all the political prisoners", "body_hi": "सरकार सभी राजनीतिक बंदियों को रिहा करने पर सहमत हो गई थी", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-non-cooperation-chauri-chaura' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'hard', body = 'Which one of the following most clearly distinguished the Quit India Movement of 1942 from the earlier mass movements led by Gandhi?', body_hi = 'निम्नलिखित में से कौन-सी बात 1942 के भारत छोड़ो आंदोलन को गांधी के नेतृत्व वाले पहले के जन-आंदोलनों से सबसे स्पष्ट रूप से अलग करती है?', explanation = 'The government struck first: on 9 August 1942, the morning after the AICC''s resolution, Gandhi and the whole Congress leadership were arrested. With no central direction, the ''August Kranti'' became a largely spontaneous rising of students, peasants and workers, with attacks on railways and telegraph lines, underground leaders such as Jayaprakash Narayan, Aruna Asaf Ali and Ram Manohar Lohia, a secret Congress Radio, and parallel governments in a few districts. It was strongest in the countryside of Bihar and eastern United Provinces, Gandhi did not call it off (it was crushed), and the Muslim League stayed out of it.', explanation_hi = 'सरकार ने पहले वार किया: AICC के प्रस्ताव के अगले दिन, 9 अगस्त 1942 की सुबह, गांधी और कांग्रेस का पूरा नेतृत्व गिरफ़्तार कर लिया गया। केंद्रीय दिशा के अभाव में ''अगस्त क्रांति'' छात्रों, किसानों और मज़दूरों का बड़े पैमाने पर स्वतःस्फूर्त विद्रोह बन गई, जिसमें रेल और तार लाइनों पर हमले हुए, जयप्रकाश नारायण, अरुणा आसफ़ अली और राम मनोहर लोहिया जैसे भूमिगत नेता उभरे, एक गुप्त कांग्रेस रेडियो चला, और कुछ ज़िलों में समानांतर सरकारें बनीं। यह बिहार और पूर्वी संयुक्त प्रांत के ग्रामीण इलाकों में सबसे प्रबल था, गांधी ने इसे वापस नहीं लिया (इसे कुचल दिया गया), और मुस्लिम लीग इससे दूर रही।', concept_group_id = 'modern-august-kranti-quit-india', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Its leaders were arrested at the outset, so it was carried on largely by local initiative and underground networks", "body_hi": "इसके नेता शुरुआत में ही गिरफ़्तार कर लिए गए, इसलिए यह मुख्यतः स्थानीय पहल और भूमिगत तंत्रों से चला", "isCorrect": true}, {"id": "b", "body": "It was confined largely to the urban middle classes and found little support among the peasants of the countryside", "body_hi": "यह मुख्यतः शहरी मध्य वर्ग तक सीमित रहा और गाँवों के किसानों में इसे बहुत कम समर्थन मिला", "isCorrect": false}, {"id": "c", "body": "It was called off by Gandhi when an outbreak of mob violence convinced him that the people were not yet ready for it", "body_hi": "भीड़ की हिंसा से जब गांधी को लगा कि लोग अभी तैयार नहीं हैं, तो उन्होंने इसे वापस ले लिया", "isCorrect": false}, {"id": "d", "body": "It was launched jointly by the Congress and the Muslim League after the two parties agreed on a common constitution", "body_hi": "कांग्रेस और मुस्लिम लीग ने एक साझा संविधान पर सहमत होने के बाद इसे मिलकर शुरू किया", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-august-kranti-quit-india' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'hard', body = 'Which of the following were included in the resolutions on Fundamental Rights and the National Economic Programme adopted at the Karachi session of the Congress in 1931?
1. Universal adult franchise
2. Free and compulsory primary education
3. Nationalisation of all agricultural land
4. Substantial reduction in rent and land revenue
5. State ownership or control of key industries and mines
Select the correct answer using the code given below.', body_hi = '1931 के कांग्रेस के कराची अधिवेशन में स्वीकृत मौलिक अधिकारों और राष्ट्रीय आर्थिक कार्यक्रम संबंधी प्रस्तावों में निम्नलिखित में से कौन-से शामिल थे?
1. सार्वभौम वयस्क मताधिकार
2. निःशुल्क और अनिवार्य प्राथमिक शिक्षा
3. सारी कृषि भूमि का राष्ट्रीयकरण
4. लगान और भू-राजस्व में पर्याप्त कमी
5. प्रमुख उद्योगों और खानों पर राज्य का स्वामित्व या नियंत्रण
नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए।', explanation = 'The Karachi session of March 1931, presided over by Vallabhbhai Patel, set out what swaraj would mean for ordinary people. The Fundamental Rights resolution promised free speech, a free press, association and assembly, equality before the law irrespective of caste, creed or sex, universal adult franchise and free and compulsory primary education. The economic programme promised a substantial reduction in rent and revenue, relief from agricultural debt and usury, better conditions and the right to form unions for workers, and state ownership or control of key industries, mines and transport. It did not call for nationalising land. Much of it reappears in Parts III and IV of the Constitution.', explanation_hi = 'मार्च 1931 के कराची अधिवेशन ने, जिसकी अध्यक्षता वल्लभभाई पटेल ने की, बताया कि आम लोगों के लिए स्वराज का क्या अर्थ होगा। मौलिक अधिकार प्रस्ताव ने अभिव्यक्ति, प्रेस, संगठन और सभा की स्वतंत्रता, जाति, पंथ या लिंग से अलग क़ानून के समक्ष समानता, सार्वभौम वयस्क मताधिकार और निःशुल्क व अनिवार्य प्राथमिक शिक्षा का वचन दिया। आर्थिक कार्यक्रम ने लगान और राजस्व में पर्याप्त कमी, कृषि ऋण और सूदख़ोरी से राहत, मज़दूरों के लिए बेहतर परिस्थितियाँ और संघ बनाने का अधिकार, तथा प्रमुख उद्योगों, खानों और परिवहन पर राज्य के स्वामित्व या नियंत्रण का वचन दिया। इसमें भूमि के राष्ट्रीयकरण की माँग नहीं थी। इसका बड़ा भाग संविधान के भाग III और IV में फिर दिखता है।', concept_group_id = 'modern-karachi-resolution-1931', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "1, 2 and 3 only", "body_hi": "केवल 1, 2 और 3", "isCorrect": false}, {"id": "b", "body": "2, 3, 4 and 5 only", "body_hi": "केवल 2, 3, 4 और 5", "isCorrect": false}, {"id": "c", "body": "1, 2, 3, 4 and 5", "body_hi": "1, 2, 3, 4 और 5", "isCorrect": false}, {"id": "d", "body": "1, 2, 4 and 5 only", "body_hi": "केवल 1, 2, 4 और 5", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-karachi-resolution-1931' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'hard', body = 'The Kuka (Namdhari) movement of Punjab under Baba Ram Singh is often described as an early form of non-cooperation. This is because it:', body_hi = 'बाबा राम सिंह के नेतृत्व में पंजाब के कूका (नामधारी) आंदोलन को प्रायः असहयोग का प्रारंभिक रूप कहा जाता है। ऐसा इसलिए कि इसने:', explanation = 'Baba Ram Singh, who organised the Namdharis from Bhaini in the late 1850s, preached the purification of Sikh practice -- simple living, no caste distinctions, no dowry -- and asked his followers to boycott British courts, English education and foreign goods and to send their messages by their own couriers rather than the post. After Kukas attacked Malerkotla in 1872, dozens were blown from guns and Ram Singh was exiled to Rangoon. The canal colony agitation of 1907 was led by Ajit Singh and Lala Lajpat Rai, and the Second Anglo-Sikh War (1848-49) came before the movement began.', explanation_hi = 'बाबा राम सिंह, जिन्होंने 1850 के दशक के अंत में भैणी से नामधारियों को संगठित किया, सिख आचरण की शुद्धि का उपदेश देते थे, जैसे सादा जीवन, जाति-भेद और दहेज़ का त्याग, और उन्होंने अनुयायियों से ब्रिटिश अदालतों, अंग्रेज़ी शिक्षा और विदेशी वस्तुओं का बहिष्कार करने तथा डाक के बजाय अपने संदेशवाहकों से संदेश भेजने को कहा। 1872 में कूकाओं के मलेरकोटला पर हमले के बाद दर्जनों को तोपों से उड़ा दिया गया और राम सिंह को रंगून निर्वासित कर दिया गया। 1907 के नहर बस्ती आंदोलन का नेतृत्व अजीत सिंह और लाला लाजपत राय ने किया था, और द्वितीय आंग्ल-सिख युद्ध (1848-49) आंदोलन के शुरू होने से पहले हुआ था।', concept_group_id = 'modern-kuka-movement-ram-singh', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "organised the first no-revenue campaign against the British in Punjab", "body_hi": "पंजाब में अंग्रेज़ों के विरुद्ध पहला लगान-बंदी अभियान संगठित किया", "isCorrect": false}, {"id": "b", "body": "boycotted British courts, schools and goods, and kept its own postal system", "body_hi": "ब्रिटिश अदालतों, स्कूलों और वस्तुओं का बहिष्कार किया, और अपनी डाक व्यवस्था रखी", "isCorrect": true}, {"id": "c", "body": "led the protests of 1907 against the canal colony laws and higher water rates", "body_hi": "1907 में नहर बस्ती क़ानूनों और बढ़ी हुई सिंचाई दरों के विरुद्ध आंदोलन का नेतृत्व किया", "isCorrect": false}, {"id": "d", "body": "asked Sikh soldiers to refuse service in the Second Anglo-Sikh War", "body_hi": "सिख सैनिकों से द्वितीय आंग्ल-सिख युद्ध में सेवा से इनकार करने को कहा", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-kuka-movement-ram-singh' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'When Bhagat Singh and Batukeshwar Dutt threw bombs into the Central Legislative Assembly in April 1929, they made sure that no one was killed and then courted arrest. Their main aim was to:', body_hi = 'अप्रैल 1929 में जब भगत सिंह और बटुकेश्वर दत्त ने केंद्रीय विधान सभा में बम फेंके, तो उन्होंने ध्यान रखा कि कोई मारा न जाए और फिर गिरफ़्तारी दी। उनका मुख्य उद्देश्य था:', explanation = 'The bombs were thrown on empty benches, and the leaflets they scattered said that it takes a loud voice to make the deaf hear. The protest was against the Public Safety Bill and the Trade Disputes Bill, aimed at revolutionaries and the labour movement. Shouting ''Inquilab Zindabad'', the two let themselves be arrested so that their trial would carry their ideas to the country. Bhagat Singh was later tried with Rajguru and Sukhdev for the killing of the police officer Saunders, and the three were hanged in March 1931. Chandrashekhar Azad died in Allahabad in February 1931, after the Assembly incident, so the last option is a chronological trap.', explanation_hi = 'बम ख़ाली बेंचों पर फेंके गए, और उनके बिखेरे पर्चों में लिखा था कि बहरों को सुनाने के लिए ऊँची आवाज़ चाहिए। विरोध पब्लिक सेफ़्टी विधेयक और ट्रेड डिस्प्यूट्स विधेयक के विरुद्ध था, जो क्रांतिकारियों और मज़दूर आंदोलन पर निशाना थे। ''इंक़लाब ज़िंदाबाद'' का नारा लगाते हुए दोनों ने गिरफ़्तारी दी, ताकि उनका मुक़दमा उनके विचार देश तक पहुँचाए। बाद में भगत सिंह पर राजगुरु और सुखदेव के साथ पुलिस अधिकारी सॉन्डर्स की हत्या का मुक़दमा चला, और मार्च 1931 में तीनों को फाँसी दी गई। चंद्रशेखर आज़ाद की मृत्यु विधान सभा की घटना के बाद, फ़रवरी 1931 में इलाहाबाद में हुई, इसलिए अंतिम विकल्प कालक्रम का जाल है।', concept_group_id = 'modern-assembly-bomb-1929', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "kill the officials who had pushed the Public Safety and Trade Disputes Bills through the Assembly", "body_hi": "उन अधिकारियों को मारना जिन्होंने विधान सभा में पब्लिक सेफ़्टी और ट्रेड डिस्प्यूट्स विधेयक पारित कराए थे", "isCorrect": false}, {"id": "b", "body": "seize the Assembly building and proclaim an independent republic", "body_hi": "विधान सभा भवन पर क़ब्ज़ा कर स्वतंत्र गणराज्य की घोषणा करना", "isCorrect": false}, {"id": "c", "body": "draw attention to their cause and use their trial as a platform for their ideas", "body_hi": "अपने उद्देश्य की ओर ध्यान खींचना और अपने मुक़दमे को अपने विचारों का मंच बनाना", "isCorrect": true}, {"id": "d", "body": "avenge the death of Chandrashekhar Azad at Allahabad", "body_hi": "इलाहाबाद में चंद्रशेखर आज़ाद की मृत्यु का बदला लेना", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-assembly-bomb-1929' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'The Battle of Wandiwash (1760) was a turning point in eighteenth-century India mainly because it:', body_hi = 'वांडिवाश का युद्ध (1760) अठारहवीं सदी के भारत में मुख्यतः इसलिए निर्णायक मोड़ था कि इसने:', explanation = 'At Wandiwash in the Carnatic, during the Third Carnatic War, Sir Eyre Coote defeated the French under Count de Lally. Pondicherry fell in 1761, and although the Treaty of Paris (1763) returned the French settlements, they could not be fortified, so the French were left as traders. Plassey (1757) made the Company the kingmaker in Bengal, and the Afghans broke Maratha power in the north at the Third Battle of Panipat (1761). The Dutch, checked by the English at Bedara in 1759, kept some of their settlements for decades.', explanation_hi = 'कर्नाटक के वांडिवाश में, तृतीय कर्नाटक युद्ध के दौरान, सर आयर कूट ने काउंट डी लैली के नेतृत्व वाले फ़्रांसीसियों को हराया। 1761 में पांडिचेरी का पतन हुआ, और यद्यपि पेरिस की संधि (1763) ने फ़्रांसीसी बस्तियाँ लौटा दीं, उनकी क़िलेबंदी नहीं हो सकती थी, इसलिए फ़्रांसीसी केवल व्यापारी रह गए। प्लासी (1757) ने कंपनी को बंगाल में राजा-निर्माता बनाया, और पानीपत के तीसरे युद्ध (1761) में अफ़गानों ने उत्तर में मराठा शक्ति तोड़ी। 1759 में बेदारा में अंग्रेज़ों से रोके गए डचों ने अपनी कुछ बस्तियाँ दशकों तक रखीं।', concept_group_id = 'modern-battle-of-wandiwash', source_citation = 'Sekhar Bandyopadhyay, From Plassey to Partition and After (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "ended the French challenge to the English East India Company in India", "body_hi": "भारत में अंग्रेज़ ईस्ट इंडिया कंपनी को मिल रही फ़्रांसीसी चुनौती समाप्त कर दी", "isCorrect": true}, {"id": "b", "body": "made the English East India Company the kingmaker in the politics of Bengal", "body_hi": "अंग्रेज़ ईस्ट इंडिया कंपनी को बंगाल की राजनीति में राजा-निर्माता बना दिया", "isCorrect": false}, {"id": "c", "body": "broke the power of the Marathas in north India for about a decade", "body_hi": "उत्तर भारत में मराठों की शक्ति को लगभग एक दशक के लिए तोड़ दिया", "isCorrect": false}, {"id": "d", "body": "ended the Dutch presence on the Coromandel coast", "body_hi": "कोरोमंडल तट पर डच उपस्थिति समाप्त कर दी", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-battle-of-wandiwash' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'Which one of the following best explains the outbreak of the Deccan riots of 1875?', body_hi = 'निम्नलिखित में से कौन-सा 1875 के दक्कन दंगों के भड़कने की सबसे अच्छी व्याख्या करता है?', explanation = 'During the American Civil War (1861-65) the demand for Indian cotton soared, and peasants in Poona and Ahmednagar borrowed to grow it; when the war ended, prices collapsed, while a revenue revision of 1867 had raised the demand. Deep in debt, peasants attacked Marwari and Gujarati moneylenders in 1875 and seized and burnt the bonds and account books that recorded their debts. The government responded with the Deccan Agriculturists'' Relief Act, 1879. Forced indigo cultivation belongs to Bengal and Bihar, the Second Afghan War began in 1878, and the famine of 1876-78 came after the riots.', explanation_hi = 'अमेरिकी गृहयुद्ध (1861-65) के दौरान भारतीय कपास की माँग बहुत बढ़ी, और पूना व अहमदनगर के किसानों ने उसे उगाने के लिए ऋण लिए; युद्ध समाप्त होते ही दाम गिर गए, जबकि 1867 के राजस्व संशोधन ने माँग बढ़ा दी थी। क़र्ज़ में डूबे किसानों ने 1875 में मारवाड़ी और गुजराती साहूकारों पर हमले किए और उनके ऋण दर्ज करने वाले बंधपत्र तथा बहीखाते छीनकर जला दिए। सरकार ने दक्कन कृषक राहत अधिनियम, 1879 से उत्तर दिया। नील की जबरन खेती बंगाल और बिहार की बात है, द्वितीय अफ़गान युद्ध 1878 में शुरू हुआ, और 1876-78 का अकाल दंगों के बाद आया।', concept_group_id = 'modern-deccan-riots-1875', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "European planters forced the peasants to grow indigo on a fixed part of their holdings at low prices", "body_hi": "यूरोपीय बागान मालिकों ने किसानों को उनकी जोत के एक निश्चित भाग पर कम दाम पर नील उगाने को मजबूर किया", "isCorrect": false}, {"id": "b", "body": "The government raised the salt tax sharply to pay for its war in Afghanistan", "body_hi": "सरकार ने अफ़गानिस्तान में अपने युद्ध का ख़र्च चलाने के लिए नमक कर तेज़ी से बढ़ा दिया", "isCorrect": false}, {"id": "c", "body": "The great famine of 1876-78 drove the starving peasants of the Deccan to loot the grain dealers'' shops", "body_hi": "1876-78 के भीषण अकाल ने दक्कन के भूखे किसानों को अनाज व्यापारियों की दुकानें लूटने पर मजबूर किया", "isCorrect": false}, {"id": "d", "body": "A fall in cotton prices after the American Civil War left peasants unable to repay their moneylenders", "body_hi": "अमेरिकी गृहयुद्ध के बाद कपास के दाम गिरने से किसान अपने साहूकारों का ऋण चुकाने में असमर्थ हो गए", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-deccan-riots-1875' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'According to Dadabhai Naoroji''s theory of the ''drain of wealth'', which of the following were channels through which India''s wealth flowed to Britain without an adequate return?
1. ''Home charges'' paid in Britain, including interest on the public debt
2. Salaries and pensions of British officials remitted to Britain
3. Profits on foreign capital invested in India
4. Expenditure on famine relief within India
Select the correct answer using the code given below.', body_hi = 'दादाभाई नौरोजी के ''धन की निकासी'' सिद्धांत के अनुसार निम्नलिखित में से कौन-से वे रास्ते थे जिनसे भारत का धन बिना पर्याप्त प्रतिफल के ब्रिटेन जाता था?
1. ब्रिटेन में चुकाए जाने वाले ''होम चार्जेज़'', जिनमें सार्वजनिक ऋण पर ब्याज शामिल है
2. ब्रिटेन भेजे जाने वाले ब्रिटिश अधिकारियों के वेतन और पेंशन
3. भारत में लगी विदेशी पूँजी पर लाभ
4. भारत के भीतर अकाल राहत पर व्यय
नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए।', explanation = 'Naoroji, in the papers collected as Poverty and Un-British Rule in India (1901), argued that a large part of India''s revenue and savings went to Britain each year without any equivalent return. The channels were the ''home charges'' -- interest on debt, the India Office''s costs, military charges and pensions paid in Britain -- the salaries and savings that British officials sent home, and the profits on British capital invested in India. Famine relief was spent within India, so it was not part of the drain. Taken up by R.C. Dutt and M.G. Ranade, the theory became the economic core of early nationalism.', explanation_hi = 'नौरोजी ने ''पॉवर्टी एंड अन-ब्रिटिश रूल इन इंडिया'' (1901) में संकलित लेखों में तर्क दिया कि भारत के राजस्व और बचत का बड़ा भाग हर वर्ष बिना किसी समान प्रतिफल के ब्रिटेन चला जाता है। इसके रास्ते थे ''होम चार्जेज़'', यानी ऋण पर ब्याज, इंडिया ऑफ़िस का ख़र्च, सैन्य व्यय और ब्रिटेन में दी जाने वाली पेंशन, ब्रिटिश अधिकारियों द्वारा घर भेजे जाने वाले वेतन और बचत, तथा भारत में लगी ब्रिटिश पूँजी पर लाभ। अकाल राहत भारत के भीतर ख़र्च होती थी, इसलिए वह निकासी का भाग नहीं थी। आर.सी. दत्त और एम.जी. रानाडे द्वारा आगे बढ़ाया गया यह सिद्धांत प्रारंभिक राष्ट्रवाद का आर्थिक आधार बन गया।', concept_group_id = 'modern-drain-theory-naoroji', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "1 and 2 only", "body_hi": "केवल 1 और 2", "isCorrect": false}, {"id": "b", "body": "1, 2 and 3 only", "body_hi": "केवल 1, 2 और 3", "isCorrect": true}, {"id": "c", "body": "2, 3 and 4 only", "body_hi": "केवल 2, 3 और 4", "isCorrect": false}, {"id": "d", "body": "1, 2, 3 and 4", "body_hi": "1, 2, 3 और 4", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-drain-theory-naoroji' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'Gandhi launched a limited ''individual satyagraha'' in October 1940, rather than a mass movement, mainly because he:', body_hi = 'गांधी ने अक्टूबर 1940 में जन-आंदोलन के बजाय सीमित ''व्यक्तिगत सत्याग्रह'' मुख्यतः इसलिए शुरू किया कि वे:', explanation = 'India had been declared a party to the war without consulting its people, and the August Offer had not met the Congress''s demands. Gandhi wanted to register the protest and assert the right to speak against the war, but did not want a mass struggle that would embarrass Britain while it stood alone against Nazi Germany. Satyagrahis were chosen one by one -- Vinoba Bhave first, Jawaharlal Nehru second -- and each courted arrest by speaking against the war effort; about 25,000 had been jailed by mid-1941. Gandhi was not in prison at the time.', explanation_hi = 'भारत को उसके लोगों से पूछे बिना युद्ध में शामिल घोषित कर दिया गया था, और अगस्त प्रस्ताव कांग्रेस की माँगें पूरी नहीं करता था। गांधी विरोध दर्ज करना और युद्ध के विरुद्ध बोलने का अधिकार जताना चाहते थे, पर ऐसा जन-संघर्ष नहीं चाहते थे जो नाज़ी जर्मनी के सामने अकेले खड़े ब्रिटेन को संकट में डाले। सत्याग्रही एक-एक कर चुने गए, पहले विनोबा भावे और दूसरे जवाहरलाल नेहरू, और हर एक ने युद्ध प्रयास के विरुद्ध बोलकर गिरफ़्तारी दी; 1941 के मध्य तक लगभग 25,000 लोग जेल जा चुके थे। उस समय गांधी जेल में नहीं थे।', concept_group_id = 'modern-individual-satyagraha-1940', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "had been released from prison on the condition that he would not launch a mass movement", "body_hi": "इस शर्त पर जेल से छोड़े गए थे कि वे कोई जन-आंदोलन शुरू नहीं करेंगे", "isCorrect": false}, {"id": "b", "body": "wanted to keep the Congress Socialists and the Communists out of the national movement", "body_hi": "कांग्रेस समाजवादियों और कम्युनिस्टों को राष्ट्रीय आंदोलन से बाहर रखना चाहते थे", "isCorrect": false}, {"id": "c", "body": "wanted to protest against the war without hampering Britain by a mass struggle", "body_hi": "जन-संघर्ष से ब्रिटेन को बाधा पहुँचाए बिना युद्ध का विरोध करना चाहते थे", "isCorrect": true}, {"id": "d", "body": "believed that Britain would leave India after the war without any further struggle", "body_hi": "मानते थे कि युद्ध के बाद ब्रिटेन बिना किसी और संघर्ष के भारत छोड़ देगा", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-individual-satyagraha-1940' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'Nationalists saw the partition of Bengal in 1905 as a policy of ''divide and rule'' because it:', body_hi = 'राष्ट्रवादियों ने 1905 के बंगाल विभाजन को ''फूट डालो और राज करो'' की नीति इसलिए माना कि इसने:', explanation = 'The new province of Eastern Bengal and Assam had a Muslim majority, while in the rest of Bengal, joined with Bihar and Orissa, Bengali speakers became a minority. Officials'' own notes show that weakening Bengal, the centre of educated nationalism, was an aim, and the Muslim leaders of the east were encouraged to see the new province as their own. No zamindari was abolished and no area was put under ''direct'' Crown rule, since all of British India already was. The partition was annulled in 1911.', explanation_hi = 'पूर्वी बंगाल और असम के नए प्रांत में मुस्लिम बहुमत था, जबकि बिहार और उड़ीसा के साथ जुड़े शेष बंगाल में बांग्ला-भाषी अल्पसंख्यक हो गए। अधिकारियों की अपनी टिप्पणियाँ दिखाती हैं कि शिक्षित राष्ट्रवाद के केंद्र बंगाल को कमज़ोर करना एक उद्देश्य था, और पूर्व के मुस्लिम नेताओं को नए प्रांत को अपना मानने के लिए प्रोत्साहित किया गया। कोई ज़मींदारी समाप्त नहीं की गई और कोई क्षेत्र ''सीधे'' ताज के शासन में नहीं रखा गया, क्योंकि पूरा ब्रिटिश भारत पहले से उसी के अधीन था। विभाजन 1911 में रद्द कर दिया गया।', concept_group_id = 'modern-partition-of-bengal-annulment', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "divided Bengalis along religious lines and made them a minority in the western province", "body_hi": "बंगालियों को धार्मिक आधार पर बाँट दिया और पश्चिमी प्रांत में उन्हें अल्पसंख्यक बना दिया", "isCorrect": true}, {"id": "b", "body": "abolished the zamindari system in the eastern districts, which hurt the Hindu landlords", "body_hi": "पूर्वी ज़िलों में ज़मींदारी व्यवस्था समाप्त कर दी, जिससे हिंदू ज़मींदारों को चोट पहुँची", "isCorrect": false}, {"id": "c", "body": "merged the Bengali-speaking districts of Bihar into the new province of Assam", "body_hi": "बिहार के बांग्ला-भाषी ज़िलों को असम के नए प्रांत में मिला दिया", "isCorrect": false}, {"id": "d", "body": "placed the whole of eastern Bengal under the direct rule of the British Crown", "body_hi": "पूरे पूर्वी बंगाल को ब्रिटिश ताज के सीधे शासन में रख दिया", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-partition-of-bengal-annulment' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'easy', body = 'Which one of the following best explains why the peasants of Kheda in Gujarat launched a satyagraha in 1918?', body_hi = 'निम्नलिखित में से कौन-सा सबसे अच्छी तरह बताता है कि 1918 में गुजरात के खेड़ा के किसानों ने सत्याग्रह क्यों शुरू किया?', explanation = 'In Kheda the crops had failed, and under the revenue code the peasants were entitled to remission if the yield fell below a quarter of the normal. When the government insisted on full collection, Gandhi, with Vallabhbhai Patel and others, led a no-revenue campaign; the government finally instructed that revenue be recovered only from those who could pay. The plague-bonus dispute was the Ahmedabad mill strike of the same year, and rents above the recorded amount were the grievance of the Eka movement in Awadh.', explanation_hi = 'खेड़ा में फ़सल नष्ट हो गई थी, और राजस्व संहिता के तहत उपज सामान्य के एक-चौथाई से कम होने पर किसान छूट के हक़दार थे। जब सरकार पूरी वसूली पर अड़ी रही, तो गांधी ने वल्लभभाई पटेल और अन्य के साथ लगान-बंदी अभियान चलाया; अंततः सरकार ने निर्देश दिया कि राजस्व केवल उन्हीं से वसूला जाए जो चुका सकते हैं। प्लेग बोनस का विवाद उसी वर्ष की अहमदाबाद मिल हड़ताल का था, और दर्ज राशि से अधिक लगान अवध के एका आंदोलन की शिकायत थी।', concept_group_id = 'modern-kheda-satyagraha-1918', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Mill owners in Ahmedabad had withdrawn the plague bonus paid to their workers", "body_hi": "अहमदाबाद के मिल मालिकों ने अपने मज़दूरों को मिलने वाला प्लेग बोनस वापस ले लिया था", "isCorrect": false}, {"id": "b", "body": "Landlords were charging rents far above the amount recorded in the rent rolls", "body_hi": "ज़मींदार लगान-बही में दर्ज राशि से बहुत अधिक लगान वसूल रहे थे", "isCorrect": false}, {"id": "c", "body": "The government had begun forcibly recruiting peasants for the army in the First World War", "body_hi": "सरकार ने प्रथम विश्व युद्ध के लिए किसानों की सेना में जबरन भर्ती शुरू कर दी थी", "isCorrect": false}, {"id": "d", "body": "The crops had failed, but the government refused to suspend land revenue", "body_hi": "फ़सल नष्ट हो गई थी, पर सरकार ने भू-राजस्व स्थगित करने से इनकार कर दिया", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-kheda-satyagraha-1918' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'The formation of the All India Kisan Sabha in 1936 is best seen as a sign of:', body_hi = '1936 में अखिल भारतीय किसान सभा के गठन को सबसे अच्छी तरह किसका संकेत माना जा सकता है?', explanation = 'The Sabha was founded at Lucknow in April 1936, at the same time as the Congress session there, with Swami Sahajanand Saraswati as president and N.G. Ranga as general secretary. Socialists and communists, then working within the Congress, wanted peasants organised around their own demands; its Kisan Manifesto asked for the abolition of zamindari, lower rents and the cancellation of debts, and it influenced the Congress''s agrarian programme adopted at Faizpur later that year. It grew out of the provincial kisan sabhas rather than replacing them. In Bengal the tenants'' party of the 1937 elections was Fazlul Huq''s Krishak Praja Party, not the League.', explanation_hi = 'सभा की स्थापना अप्रैल 1936 में लखनऊ में, वहीं के कांग्रेस अधिवेशन के साथ, हुई, जिसके अध्यक्ष स्वामी सहजानंद सरस्वती और महासचिव एन.जी. रंगा थे। उस समय कांग्रेस के भीतर काम कर रहे समाजवादी और कम्युनिस्ट चाहते थे कि किसान अपनी माँगों पर संगठित हों; इसके किसान घोषणापत्र ने ज़मींदारी उन्मूलन, कम लगान और ऋण-माफ़ी की माँग की, और इसने उसी वर्ष फ़ैज़पुर में स्वीकृत कांग्रेस के कृषि कार्यक्रम को प्रभावित किया। यह प्रांतीय किसान सभाओं से निकली, उनकी जगह नहीं ली। बंगाल में 1937 के चुनावों में काश्तकारों का दल फ़ज़लुल हक़ की कृषक प्रजा पार्टी था, लीग नहीं।', concept_group_id = 'modern-all-india-kisan-sabha-1936', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "a Congress decision to replace the provincial kisan sabhas with a single wing under its Working Committee", "body_hi": "प्रांतीय किसान सभाओं की जगह अपनी कार्यसमिति के अधीन एक ही शाखा बनाने के कांग्रेस के निर्णय का", "isCorrect": false}, {"id": "b", "body": "the rise of the Left in the national movement, seeking to organise peasants on their own demands", "body_hi": "राष्ट्रीय आंदोलन में वामपंथ के उभार का, जो किसानों को उनकी अपनी माँगों पर संगठित करना चाहता था", "isCorrect": true}, {"id": "c", "body": "the Muslim League''s effort to win over the tenants of eastern Bengal before the 1937 elections", "body_hi": "1937 के चुनावों से पहले पूर्वी बंगाल के काश्तकारों को अपनी ओर करने के मुस्लिम लीग के प्रयास का", "isCorrect": false}, {"id": "d", "body": "the government''s attempt to build a loyal body of peasants to counter the Congress", "body_hi": "कांग्रेस का सामना करने के लिए किसानों का एक वफ़ादार निकाय बनाने के सरकार के प्रयास का", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-all-india-kisan-sabha-1936' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'easy', body = 'The Theosophical Society, founded in 1875, influenced Indian public life mainly because it:', body_hi = '1875 में स्थापित थियोसोफ़िकल सोसाइटी ने भारतीय सार्वजनिक जीवन को मुख्यतः इसलिए प्रभावित किया कि इसने:', explanation = 'Founded in New York by Madame Blavatsky and Colonel Olcott, the Society moved its headquarters to Adyar near Madras in 1882. Coming from Westerners, its praise of ancient Hindu and Buddhist philosophy gave educated Indians, who were told their culture was backward, a new pride. Annie Besant, who led it from 1907, later founded a Home Rule League (1916). The Society did not demand independence, opposed missionary conversion rather than supporting it, and drew heavily on the Upanishads.', explanation_hi = 'न्यूयॉर्क में मैडम ब्लावात्स्की और कर्नल ऑलकॉट द्वारा स्थापित सोसाइटी ने 1882 में अपना मुख्यालय मद्रास के पास अडयार में स्थानांतरित किया। पश्चिमी लोगों की ओर से आई प्राचीन हिंदू और बौद्ध दर्शन की इसकी प्रशंसा ने उन शिक्षित भारतीयों को नया गर्व दिया, जिनसे कहा जाता था कि उनकी संस्कृति पिछड़ी है। 1907 से इसका नेतृत्व करने वाली एनी बेसेंट ने बाद में एक होम रूल लीग (1916) बनाई। सोसाइटी ने स्वतंत्रता की माँग नहीं की, मिशनरी धर्मांतरण का समर्थन नहीं बल्कि विरोध किया, और उपनिषदों पर बहुत आधारित रही।', concept_group_id = 'modern-theosophical-society-1875', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "was the first organisation to demand complete independence for India from British rule", "body_hi": "ब्रिटिश शासन से भारत की पूर्ण स्वतंत्रता की माँग करने वाला पहला संगठन था", "isCorrect": false}, {"id": "b", "body": "campaigned for the conversion of Hindus to Christianity", "body_hi": "हिंदुओं के ईसाई धर्म में धर्मांतरण के लिए अभियान चलाया", "isCorrect": false}, {"id": "c", "body": "praised ancient Hindu and Buddhist thought and raised Indians'' self-confidence", "body_hi": "प्राचीन हिंदू और बौद्ध चिंतन की प्रशंसा की और भारतीयों का आत्मविश्वास बढ़ाया", "isCorrect": true}, {"id": "d", "body": "rejected the authority of all ancient texts, including the Vedas and the Upanishads", "body_hi": "वेदों और उपनिषदों सहित सभी प्राचीन ग्रंथों के प्रामाण्य को अस्वीकार किया", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-theosophical-society-1875' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'The Poona Sarvajanik Sabha (1870), built up by M.G. Ranade and others, is regarded as an important pre-Congress body mainly because it:', body_hi = 'एम.जी. रानाडे और अन्य द्वारा विकसित पूना सार्वजनिक सभा (1870) को कांग्रेस से पहले का महत्वपूर्ण निकाय मुख्यतः इसलिए माना जाता है कि इसने:', explanation = 'The Sabha, with Ranade, G.V. Joshi and others, studied questions such as the land revenue settlements and the famine of 1876-77 and put carefully argued petitions before the government. Its quarterly journal made it a model of informed constitutional agitation in western India. The all-India conference of 1883 was organised by the Indian Association of Calcutta; the Sabha did not demand an end to British rule, and it was founded fifteen years before the Congress, so it could not have been its branch.', explanation_hi = 'रानाडे, जी.वी. जोशी और अन्य के साथ सभा ने भू-राजस्व बंदोबस्त और 1876-77 के अकाल जैसे प्रश्नों का अध्ययन किया और सरकार के सामने तर्कपूर्ण याचिकाएँ रखीं। इसकी त्रैमासिक पत्रिका ने इसे पश्चिमी भारत में सूचित संवैधानिक आंदोलन का आदर्श बनाया। 1883 का अखिल भारतीय सम्मेलन कलकत्ता की इंडियन एसोसिएशन ने आयोजित किया था; सभा ने ब्रिटिश शासन के अंत की माँग नहीं की, और यह कांग्रेस से पंद्रह वर्ष पहले बनी थी, इसलिए उसकी शाखा नहीं हो सकती थी।', concept_group_id = 'modern-poona-sarvajanik-sabha', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "studied land revenue and famine relief and petitioned the government on them", "body_hi": "भू-राजस्व और अकाल राहत का अध्ययन किया और उन पर सरकार को याचिकाएँ दीं", "isCorrect": true}, {"id": "b", "body": "organised the first all-India conference of nationalists, two years before the Congress", "body_hi": "कांग्रेस से दो वर्ष पहले राष्ट्रवादियों का पहला अखिल भारतीय सम्मेलन आयोजित किया", "isCorrect": false}, {"id": "c", "body": "called for an immediate end to British rule over the whole of the Bombay Presidency", "body_hi": "पूरी बंबई प्रेसीडेंसी पर ब्रिटिश शासन के तत्काल अंत की माँग की", "isCorrect": false}, {"id": "d", "body": "worked as the provincial branch of the Indian National Congress in the Deccan", "body_hi": "दक्कन में भारतीय राष्ट्रीय कांग्रेस की प्रांतीय शाखा के रूप में काम किया", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-poona-sarvajanik-sabha' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'medium', body = 'Which one of the following was a consequence of the Permanent Settlement introduced in Bengal in 1793?', body_hi = '1793 में बंगाल में लागू स्थायी बंदोबस्त का निम्नलिखित में से कौन-सा परिणाम था?', explanation = 'Under the ''sunset law'' a zamindar who did not pay the revenue by sunset on the due date could have his estate auctioned, and the demand had been set very high. In the first decades many old zamindari families lost all or part of their lands, often to merchants and officials with ready money. The peasants were left at the mercy of the zamindars, who were given wide powers over them, and their occupancy rights were protected only by later tenancy laws such as the Bengal Tenancy Act of 1885. Estates became freely saleable property, and famines continued.', explanation_hi = '''सूर्यास्त क़ानून'' के तहत जो ज़मींदार नियत तिथि के सूर्यास्त तक राजस्व न चुकाता, उसकी जागीर नीलाम हो सकती थी, और माँग बहुत ऊँची रखी गई थी। पहले दशकों में कई पुराने ज़मींदार परिवारों ने अपनी पूरी या आंशिक भूमि खो दी, प्रायः नक़द धन वाले व्यापारियों और अधिकारियों के हाथों। किसान ज़मींदारों की दया पर छोड़ दिए गए, जिन्हें उन पर व्यापक शक्तियाँ दी गईं, और उनके अधिभोग अधिकार बाद के बंगाल काश्तकारी अधिनियम, 1885 जैसे क़ानूनों से ही सुरक्षित हुए। जागीरें स्वतंत्र रूप से बिकने वाली संपत्ति बन गईं, और अकाल जारी रहे।', concept_group_id = 'modern-cornwallis-permanent-settlement', source_citation = 'Sekhar Bandyopadhyay, From Plassey to Partition and After (Orient BlackSwan)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "The peasants gained permanent and heritable rights of occupancy over the land they tilled", "body_hi": "किसानों को उनके द्वारा जोती जाने वाली भूमि पर स्थायी और पैतृक अधिभोग अधिकार मिले", "isCorrect": false}, {"id": "b", "body": "The zamindars were forbidden to sell, mortgage or divide their estates among heirs", "body_hi": "ज़मींदारों को अपनी जागीरें बेचने, गिरवी रखने या वारिसों में बाँटने की मनाही कर दी गई", "isCorrect": false}, {"id": "c", "body": "Famines in Bengal ended, because the zamindars now invested in irrigation", "body_hi": "बंगाल में अकाल समाप्त हो गए, क्योंकि ज़मींदार अब सिंचाई में निवेश करने लगे", "isCorrect": false}, {"id": "d", "body": "Many old zamindari families lost their estates when they failed to pay on time", "body_hi": "कई पुराने ज़मींदार परिवार समय पर भुगतान न कर पाने से अपनी जागीरें खो बैठे", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-cornwallis-permanent-settlement' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'easy', body = 'The Indian Councils Act, 1909 was passed during the viceroyalty of:', body_hi = 'भारतीय परिषद अधिनियम, 1909 किसके वायसरॉय काल में पारित हुआ?', explanation = 'The Act is known as the Morley-Minto Reforms, after the Secretary of State John Morley and the Viceroy Lord Minto II (1905-10). It enlarged the legislative councils, let members move resolutions and ask supplementary questions, and brought the first Indian into the Viceroy''s Executive Council. Curzon (1899-1905) preceded Minto, Hardinge II (1910-16) followed him, and the next reforms, of 1919, came under Chelmsford.', explanation_hi = 'यह अधिनियम भारत सचिव जॉन मॉर्ले और वायसरॉय लॉर्ड मिंटो द्वितीय (1905-10) के नाम पर मॉर्ले-मिंटो सुधार कहलाता है। इसने विधान परिषदों का विस्तार किया, सदस्यों को प्रस्ताव रखने और पूरक प्रश्न पूछने का अधिकार दिया, और वायसरॉय की कार्यकारी परिषद में पहले भारतीय को लाया। कर्ज़न (1899-1905) मिंटो से पहले थे, हार्डिंग द्वितीय (1910-16) उनके बाद आए, और अगले सुधार, 1919 के, चेम्सफ़ोर्ड के समय आए।', concept_group_id = 'modern-morley-minto-viceroy', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Lord Curzon", "body_hi": "लॉर्ड कर्ज़न", "isCorrect": false}, {"id": "b", "body": "Lord Minto", "body_hi": "लॉर्ड मिंटो", "isCorrect": true}, {"id": "c", "body": "Lord Hardinge", "body_hi": "लॉर्ड हार्डिंग", "isCorrect": false}, {"id": "d", "body": "Lord Chelmsford", "body_hi": "लॉर्ड चेम्सफ़ोर्ड", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-morley-minto-viceroy' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Raja Ram Mohan Roy argued that the oldest Hindu scriptures, the Vedas and the Upanishads, taught the worship of one God and did not sanction practices such as Sati. Consider the following statements:', body_hi = 'राजा राममोहन राय का तर्क था कि सबसे प्राचीन हिंदू ग्रंथ, वेद और उपनिषद, एक ईश्वर की उपासना सिखाते हैं और सती जैसी प्रथाओं को मान्यता नहीं देते। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 follow. By translating the Upanishads and appealing to them, Ram Mohan Roy argued that idol worship and Sati were later corruptions, so reform meant a return to the purer original tradition, which he also held to be rational. Statement 2 does not follow: he relied on the scriptures rather than rejecting them. He founded the Brahmo Sabha in Calcutta in 1828, later the Brahmo Samaj, and his campaign helped Lord William Bentinck abolish Sati by the Regulation of 1829.', explanation_hi = 'कथन 1 और 3 निष्कर्ष के रूप में निकलते हैं। उपनिषदों का अनुवाद कर और उनका हवाला देकर राममोहन राय ने तर्क दिया कि मूर्तिपूजा और सती बाद की विकृतियाँ हैं, इसलिए सुधार का अर्थ अधिक शुद्ध मूल परंपरा की ओर लौटना है, जिसे वे तर्कसंगत भी मानते थे। कथन 2 नहीं निकलता: वे ग्रंथों को अस्वीकार करने के बजाय उन पर आधारित थे। उन्होंने 1828 में कलकत्ता में ब्रह्म सभा की स्थापना की, जो बाद में ब्रह्म समाज बनी, और उनके अभियान ने लॉर्ड विलियम बेंटिक को 1829 के विनियम से सती समाप्त करने में मदद दी।', concept_group_id = 'modern-brahmo-samaj-1828', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["He sought to reform Hindu practice from within its own tradition.", "He rejected the authority of all religious texts.", "He believed that reason and the ancient scriptures pointed the same way."], "statements_hi": ["उन्होंने हिंदू आचरण का सुधार उसकी अपनी परंपरा के भीतर से करना चाहा।", "उन्होंने सभी धार्मिक ग्रंथों के प्रामाण्य को अस्वीकार किया।", "वे मानते थे कि तर्क और प्राचीन ग्रंथ एक ही दिशा दिखाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-brahmo-samaj-1828' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following early newspapers and journals:', body_hi = 'निम्नलिखित प्रारंभिक समाचार-पत्रों और पत्रिकाओं पर विचार कीजिए:', explanation = 'Three were started by Indians. Raja Ram Mohan Roy brought out the Bengali Sambad Kaumudi (1821) and the Persian Mirat-ul-Akhbar (1822), and Fardunjee Marzban started the Gujarati Bombay Samachar in 1822, which still appears. Hicky''s Bengal Gazette (1780), the first newspaper published in India, was the work of James Augustus Hicky, an Irishman; it was closed within two years for attacking Warren Hastings.', explanation_hi = 'तीन भारतीयों द्वारा शुरू किए गए। राजा राममोहन राय ने बांग्ला संवाद कौमुदी (1821) और फ़ारसी मिरात-उल-अख़बार (1822) निकाले, और फ़रदूनजी मर्ज़बान ने 1822 में गुजराती बॉम्बे समाचार शुरू किया, जो आज भी निकलता है। भारत में प्रकाशित पहला समाचार-पत्र हिकी का बंगाल गज़ट (1780) आयरिश व्यक्ति जेम्स ऑगस्टस हिकी का काम था; वॉरेन हेस्टिंग्स पर प्रहार के कारण इसे दो वर्ष के भीतर बंद कर दिया गया।', concept_group_id = 'modern-early-press', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Hicky''s Bengal Gazette", "Sambad Kaumudi", "Mirat-ul-Akhbar", "Bombay Samachar"], "statements_hi": ["हिकी का बंगाल गज़ट", "संवाद कौमुदी", "मिरात-उल-अख़बार", "बॉम्बे समाचार"], "closing": "How many of the above were started by Indians?", "closing_hi": "उपर्युक्त में से कितने भारतीयों द्वारा शुरू किए गए थे?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-early-press' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Wood''s Despatch of 1854 proposed vernacular primary schools in the districts, Anglo-vernacular high schools and colleges, and universities in the presidency towns. Consider the following statements:', body_hi = '1854 के वुड डिस्पैच ने ज़िलों में देशी भाषा के प्राथमिक विद्यालयों, आंग्ल-देशी भाषा के उच्च विद्यालयों और कॉलेजों, तथा प्रेसीडेंसी नगरों में विश्वविद्यालयों का प्रस्ताव रखा। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. After Macaulay''s Minute of 1835 the government had backed English education for a few, expecting it to ''filter down''. Wood''s Despatch, often called the ''Magna Carta of English education in India'', instead proposed a whole ladder from vernacular village schools upwards, with grants-in-aid, teacher training and attention to women''s education, Statement 2 is wrong: the Despatch wanted the vernacular at the primary level and English mainly in higher education. Statement 3 is wrong: the universities it proposed, set up at Calcutta, Bombay and Madras in 1857, followed the University of London -- affiliating and examining bodies, not residential teaching ones.', explanation_hi = 'केवल कथन 1 सही है। 1835 के मैकाले के विवरण-पत्र के बाद सरकार ने कुछ लोगों के लिए अंग्रेज़ी शिक्षा का समर्थन किया था, यह मानते हुए कि ज्ञान ''छनकर'' नीचे पहुँचेगा। प्रायः ''भारत में अंग्रेज़ी शिक्षा का मैग्ना कार्टा'' कहा जाने वाला वुड डिस्पैच इसके बजाय देशी भाषा के ग्राम विद्यालयों से ऊपर तक पूरी सीढ़ी का प्रस्ताव रखता था, जिसमें अनुदान, शिक्षक-प्रशिक्षण और स्त्री-शिक्षा पर ध्यान था, कथन 2 गलत है: डिस्पैच प्राथमिक स्तर पर देशी भाषा और मुख्यतः उच्च शिक्षा में अंग्रेज़ी चाहता था। कथन 3 गलत है: इसके प्रस्तावित विश्वविद्यालय, जो 1857 में कलकत्ता, बंबई और मद्रास में बने, लंदन विश्वविद्यालय के मॉडल पर थे, यानी संबद्धता देने और परीक्षा लेने वाली संस्थाएँ, आवासीय शिक्षण संस्थाएँ नहीं।', concept_group_id = 'modern-education-macaulay-wood', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["It departed from the idea that educating a small elite in English would be enough for knowledge to ''filter down'' to the masses.", "It made English the only medium of instruction at every level.", "It recommended that the new universities be residential teaching bodies on the model of Oxford and Cambridge."], "statements_hi": ["इसने इस विचार से हटकर काम किया कि अंग्रेज़ी में एक छोटे अभिजात वर्ग को शिक्षित करना ही जनता तक ज्ञान ''छनकर'' पहुँचाने के लिए काफ़ी है।", "इसने हर स्तर पर अंग्रेज़ी को शिक्षा का एकमात्र माध्यम बना दिया।", "इसने सिफ़ारिश की कि नए विश्वविद्यालय ऑक्सफ़ोर्ड और कैम्ब्रिज के मॉडल पर आवासीय शिक्षण संस्थाएँ हों।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-education-macaulay-wood' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. Telegraph lines linking Calcutta, Agra, Bombay, Madras and Peshawar were laid from 1853, and news and orders sent along them let the British move troops quickly in 1857. The first train ran from Bombay to Thane in 1853. The lines were built by British companies guaranteed a return of five per cent, and their routes and freight rates favoured carrying raw materials to the ports and British goods inland, so the nationalist critics argued that they served the colonial economy more than Indian industry.', explanation_hi = 'दोनों कथन सही हैं। कलकत्ता, आगरा, बंबई, मद्रास और पेशावर को जोड़ने वाली तार लाइनें 1853 से बिछाई गईं, और उनसे भेजी गई ख़बरों और आदेशों ने 1857 में अंग्रेज़ों को तेज़ी से सेना भेजने दी। पहली रेलगाड़ी 1853 में बंबई से ठाणे चली। लाइनें ऐसी ब्रिटिश कंपनियों ने बनाईं जिन्हें पाँच प्रतिशत लाभ की गारंटी थी, और उनके मार्ग तथा भाड़ा दरें कच्चे माल को बंदरगाहों तक और ब्रिटिश माल को भीतर तक ले जाने के पक्ष में थीं, इसलिए राष्ट्रवादी आलोचकों का तर्क था कि वे भारतीय उद्योग से अधिक औपनिवेशिक अर्थव्यवस्था की सेवा करती थीं।', concept_group_id = 'modern-first-railway-telegraph', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["The telegraph lines laid under Lord Dalhousie helped the British to put down the revolt of 1857.", "The early railway lines were planned mainly to link the ports with the interior and to move troops, rather than to promote Indian industry."], "statements_hi": ["लॉर्ड डलहौज़ी के समय बिछाई गई तार लाइनों ने अंग्रेज़ों को 1857 का विद्रोह दबाने में मदद दी।", "शुरुआती रेल लाइनें भारतीय उद्योग को बढ़ावा देने के बजाय मुख्यतः बंदरगाहों को भीतरी इलाकों से जोड़ने और सेना की आवाजाही के लिए बनाई गईं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-first-railway-telegraph' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. The revolt convinced Parliament that a trading company could no longer govern India, so the Act of 1858 transferred power to the Crown, created a Secretary of State for India with a Council of India, and gave the Governor-General the title of Viceroy. The Queen''s Proclamation, read out at Allahabad in November 1858, also promised not to interfere in religion. Since the princes had largely stood by the British, the policy of annexation was dropped and they were kept as allies.', explanation_hi = 'दोनों कथन सही हैं। विद्रोह ने संसद को आश्वस्त किया कि एक व्यापारिक कंपनी अब भारत का शासन नहीं चला सकती, इसलिए 1858 के अधिनियम ने सत्ता ताज को सौंपी, भारत परिषद के साथ भारत सचिव का पद बनाया, और गवर्नर-जनरल को वायसरॉय की उपाधि दी। नवंबर 1858 में इलाहाबाद में पढ़ी गई महारानी की उद्घोषणा ने धर्म में हस्तक्षेप न करने का वचन भी दिया। चूँकि राजा बड़े पैमाने पर अंग्रेज़ों के साथ खड़े रहे थे, इसलिए विलय की नीति छोड़ दी गई और उन्हें सहयोगी बनाए रखा गया।', concept_group_id = 'modern-goi-act-1858', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["The Government of India Act, 1858, which ended the East India Company''s rule, was a consequence of the Revolt of 1857.", "Queen Victoria''s Proclamation of 1858 promised the Indian princes that their territories would not be annexed and their rights would be respected."], "statements_hi": ["ईस्ट इंडिया कंपनी का शासन समाप्त करने वाला भारत सरकार अधिनियम, 1858 1857 के विद्रोह का परिणाम था।", "1858 की महारानी विक्टोरिया की उद्घोषणा ने भारतीय राजाओं को वचन दिया कि उनके राज्य नहीं मिलाए जाएँगे और उनके अधिकारों का सम्मान होगा।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-goi-act-1858' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the trials of officers of the Indian National Army at the Red Fort in 1945-46:', body_hi = '1945-46 में लाल क़िले में आज़ाद हिंद फ़ौज के अधिकारियों पर चले मुक़दमों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. P.K. Sahgal, Shah Nawaz Khan and G.S. Dhillon were tried together, and their defence by Bhulabhai Desai, Tej Bahadur Sapru, Jawaharlal Nehru and others drew in people of every community; the agitation spread to the army itself. Faced with this, the Commander-in-Chief, Auchinleck, remitted their sentences in January 1946. Statement 2 is wrong: the Muslim League too supported the INA men and defended its own members among them, and students of every party joined the protests in Calcutta.', explanation_hi = 'कथन 1 और 3 सही हैं। पी.के. सहगल, शाहनवाज़ ख़ान और जी.एस. ढिल्लों पर साथ-साथ मुक़दमा चला, और भूलाभाई देसाई, तेज बहादुर सप्रू, जवाहरलाल नेहरू तथा अन्य द्वारा उनकी पैरवी ने हर समुदाय के लोगों को जोड़ा; आंदोलन सेना तक फैल गया। इसके सामने सेनापति ऑकिनलेक ने जनवरी 1946 में उनकी सज़ाएँ माफ़ कर दीं। कथन 2 गलत है: मुस्लिम लीग ने भी आज़ाद हिंद फ़ौज के लोगों का समर्थन किया और उनमें अपने सदस्यों की पैरवी की, और कलकत्ता के प्रदर्शनों में हर दल के छात्र शामिल हुए।', concept_group_id = 'modern-ina-azad-hind', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["The first three officers tried were a Hindu, a Muslim and a Sikh, which helped make the trials a symbol of national unity.", "The Muslim League kept away from the agitation for the release of the INA men.", "Though the court martial sentenced them to transportation for life, the Commander-in-Chief remitted the sentences."], "statements_hi": ["मुक़दमे का सामना करने वाले पहले तीन अधिकारी एक हिंदू, एक मुसलमान और एक सिख थे, जिससे ये मुक़दमे राष्ट्रीय एकता का प्रतीक बने।", "मुस्लिम लीग आज़ाद हिंद फ़ौज के लोगों की रिहाई के आंदोलन से दूर रही।", "यद्यपि सैन्य अदालत ने उन्हें आजीवन देश-निकाले की सज़ा दी, सेनापति ने सज़ाएँ माफ़ कर दीं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-ina-azad-hind' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. Naoroji won Finsbury Central in 1892 as a Liberal, the first Indian in the House of Commons. Statement 2 is the trap: the House did pass a resolution for simultaneous examinations in 1893, but it was not carried out, and the examination was held in India as well only from 1922. Since the examination was held only in London, and the maximum age had been lowered to 19 in 1876, few Indians could compete, which is why the Indian Association and the early Congress made simultaneous examinations a leading demand.', explanation_hi = 'केवल कथन 1 सही है। नौरोजी 1892 में लिबरल के रूप में फ़िन्सबरी सेंट्रल से जीते, हाउस ऑफ़ कॉमन्स में पहुँचने वाले पहले भारतीय। कथन 2 जाल है: सदन ने 1893 में एक साथ परीक्षाओं का प्रस्ताव पारित तो किया, पर उस पर अमल नहीं हुआ, और परीक्षा भारत में भी 1922 से ही होने लगी। चूँकि परीक्षा केवल लंदन में होती थी, और 1876 में अधिकतम आयु घटाकर 19 कर दी गई थी, इसलिए कम भारतीय प्रतियोगिता में उतर पाते थे; इसी कारण इंडियन एसोसिएशन और प्रारंभिक कांग्रेस ने एक साथ परीक्षाओं को प्रमुख माँग बनाया।', concept_group_id = 'modern-naoroji-house-of-commons', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Dadabhai Naoroji used his seat in the British House of Commons to press for holding the civil service examination in India as well as in England.", "The demand was met in 1893, when the civil service examination began to be held in India as well."], "statements_hi": ["दादाभाई नौरोजी ने ब्रिटिश हाउस ऑफ़ कॉमन्स में अपनी सीट का उपयोग सिविल सेवा परीक्षा इंग्लैंड के साथ भारत में भी कराने की माँग के लिए किया।", "यह माँग 1893 में पूरी हुई, जब सिविल सेवा परीक्षा भारत में भी होने लगी।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-naoroji-house-of-commons' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following struggles:', body_hi = 'निम्नलिखित संघर्षों पर विचार कीजिए:', explanation = 'Gandhi personally led three of them. At Champaran he took up the indigo cultivators'' grievances against European planters; at Ahmedabad he led the mill workers'' demand for higher wages and went on his first fast in India; and in Kheda he led the no-revenue campaign with Vallabhbhai Patel. The Bardoli satyagraha of 1928, against a steep revenue increase, was led by Vallabhbhai Patel, who earned the title ''Sardar'' there; Gandhi supported it from outside.', explanation_hi = 'गांधी ने इनमें से तीन का स्वयं नेतृत्व किया। चंपारण में उन्होंने यूरोपीय बागान मालिकों के विरुद्ध नील किसानों की शिकायतें उठाईं; अहमदाबाद में उन्होंने अधिक मज़दूरी की मिल मज़दूरों की माँग का नेतृत्व किया और भारत में अपना पहला उपवास किया; और खेड़ा में उन्होंने वल्लभभाई पटेल के साथ लगान-बंदी अभियान चलाया। भारी राजस्व वृद्धि के विरुद्ध 1928 के बारदोली सत्याग्रह का नेतृत्व वल्लभभाई पटेल ने किया, जिन्हें वहीं ''सरदार'' की उपाधि मिली; गांधी ने बाहर से इसका समर्थन किया।', concept_group_id = 'modern-peasant-movements-places', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["Champaran, 1917", "Ahmedabad mill strike, 1918", "Kheda, 1918", "Bardoli, 1928"], "statements_hi": ["चंपारण, 1917", "अहमदाबाद मिल हड़ताल, 1918", "खेड़ा, 1918", "बारदोली, 1928"], "closing": "In how many of the above did Gandhi personally lead the struggle?", "closing_hi": "उपर्युक्त में से कितने संघर्षों का नेतृत्व गांधी ने स्वयं किया?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-peasant-movements-places' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. The Indian Statutory Commission, appointed in November 1927 to review the reforms of 1919, had no Indian member, which Indians took as an insult; the Congress, a section of the Muslim League under Jinnah and the Hindu Mahasabha boycotted it, and it was met with black flags and ''Simon Go Back''. The Secretary of State, Lord Birkenhead, had taunted Indians to produce an agreed constitution, and an All Parties Conference set up the committee under Motilal Nehru whose report appeared in 1928.', explanation_hi = 'दोनों कथन सही हैं। 1919 के सुधारों की समीक्षा के लिए नवंबर 1927 में नियुक्त भारतीय वैधानिक आयोग में कोई भारतीय सदस्य नहीं था, जिसे भारतीयों ने अपमान माना; कांग्रेस, जिन्ना के नेतृत्व वाले मुस्लिम लीग के एक धड़े और हिंदू महासभा ने इसका बहिष्कार किया, और इसका स्वागत काले झंडों और ''साइमन वापस जाओ'' से हुआ। भारत सचिव लॉर्ड बर्कनहेड ने भारतीयों को एक सर्वसम्मत संविधान बनाकर दिखाने की चुनौती दी थी, और एक सर्वदलीय सम्मेलन ने मोतीलाल नेहरू के नेतृत्व में समिति बनाई, जिसकी रिपोर्ट 1928 में आई।', concept_group_id = 'modern-simon-commission-composition', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["The appointment of an all-white Simon Commission united Indian parties of many shades in boycotting it.", "The Nehru Report of 1928 was drafted partly to answer the British challenge that Indians could not agree on a constitution."], "statements_hi": ["पूरी तरह श्वेत सदस्यों वाले साइमन आयोग की नियुक्ति ने कई रंगों के भारतीय दलों को उसके बहिष्कार में एकजुट कर दिया।", "1928 की नेहरू रिपोर्ट आंशिक रूप से इस ब्रिटिश चुनौती के उत्तर में तैयार की गई कि भारतीय किसी संविधान पर सहमत नहीं हो सकते।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-simon-commission-composition' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the causes of tribal uprisings:', body_hi = 'जनजातीय विद्रोहों के कारणों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct. The Santhals of the Rajmahal hills, led by Sidhu and Kanhu, rose against the moneylenders and zamindars who had reduced them to debt bondage and against the officials who backed them; a separate Santhal Parganas district followed. Birsa Munda''s Ulgulan (1899-1900) in Chota Nagpur sought to restore the khuntkatti system of joint ownership that outsiders had broken up, and led to the Chota Nagpur Tenancy Act of 1908. In the Rampa hills of the Godavari agency, Alluri Sitarama Raju led the tribals against forest laws that restricted shifting cultivation and grazing, until he was killed in 1924.', explanation_hi = 'तीनों कथन सही हैं। राजमहल पहाड़ियों के संथाल सिद्धू और कान्हू के नेतृत्व में उन साहूकारों और ज़मींदारों के विरुद्ध उठे जिन्होंने उन्हें ऋण-दासता में धकेल दिया था, और उनका साथ देने वाले अधिकारियों के विरुद्ध भी; इसके बाद एक अलग संथाल परगना ज़िला बना। छोटानागपुर में बिरसा मुंडा का उलगुलान (1899-1900) संयुक्त स्वामित्व वाली उस खुंटकट्टी व्यवस्था को बहाल करना चाहता था जिसे बाहरी लोगों ने तोड़ दिया था, और इसके बाद छोटानागपुर काश्तकारी अधिनियम, 1908 बना। गोदावरी एजेंसी की रम्पा पहाड़ियों में अल्लूरी सीताराम राजू ने झूम खेती और चराई पर रोक लगाने वाले वन क़ानूनों के विरुद्ध जनजातियों का नेतृत्व किया, जब तक 1924 में वे मारे नहीं गए।', concept_group_id = 'modern-tribal-uprisings-santhal-munda-rampa', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["The Santhal Hul of 1855-56 was directed against moneylenders and zamindars as well as the police and officials who protected them.", "Birsa Munda''s movement sought to restore the Mundas'' traditional rights over land that outsiders had taken over.", "The Rampa rebellion of 1922-24 was a protest against restrictions on the tribals'' use of the forests."], "statements_hi": ["1855-56 का संथाल हूल साहूकारों और ज़मींदारों के साथ-साथ उनकी रक्षा करने वाली पुलिस और अधिकारियों के विरुद्ध था।", "बिरसा मुंडा का आंदोलन उस भूमि पर मुंडाओं के पारंपरिक अधिकार बहाल करना चाहता था जिसे बाहरी लोगों ने हथिया लिया था।", "1922-24 का रम्पा विद्रोह जनजातियों के वन-उपयोग पर लगी पाबंदियों के विरुद्ध विरोध था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-tribal-uprisings-santhal-munda-rampa' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements:', body_hi = 'निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. Vidyasagar collected petitions and argued from the Parashara Smriti that the shastras allowed widows to remarry, so that reform could not be dismissed as an alien idea; the Act of 1856 followed. Yet few remarriages took place, and Vidyasagar arranged many himself, at great cost to his own fortune, because the orthodox continued to ostracise those involved. The gap between legal change and social practice is a recurring theme of nineteenth-century reform.', explanation_hi = 'दोनों कथन सही हैं। विद्यासागर ने याचिकाएँ जुटाईं और पराशर स्मृति के आधार पर तर्क दिया कि शास्त्र विधवाओं को पुनर्विवाह की अनुमति देते हैं, ताकि सुधार को विदेशी विचार कहकर ख़ारिज न किया जा सके; इसके बाद 1856 का अधिनियम आया। फिर भी कम पुनर्विवाह हुए, और विद्यासागर ने अपनी संपत्ति की भारी क़ीमत पर कई स्वयं कराए, क्योंकि रूढ़िवादी लोग इनमें शामिल लोगों का बहिष्कार करते रहे। क़ानूनी बदलाव और सामाजिक आचरण के बीच का अंतर उन्नीसवीं सदी के सुधार का बार-बार आने वाला विषय है।', concept_group_id = 'modern-widow-remarriage-sarda-act', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Ishwar Chandra Vidyasagar based his case for widow remarriage on the shastras, arguing that they permitted it.", "The Hindu Widows'' Remarriage Act of 1856 made such marriages legal but did not by itself make them socially accepted."], "statements_hi": ["ईश्वरचंद्र विद्यासागर ने विधवा पुनर्विवाह का पक्ष शास्त्रों पर आधारित किया, यह तर्क देते हुए कि वे इसकी अनुमति देते हैं।", "1856 के हिंदू विधवा पुनर्विवाह अधिनियम ने ऐसे विवाहों को वैध बनाया, पर अपने आप में उन्हें सामाजिक स्वीकृति नहीं दिलाई।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-widow-remarriage-sarda-act' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following women:', body_hi = 'निम्नलिखित महिलाओं पर विचार कीजिए:', explanation = 'Three of them presided. Annie Besant was the first woman president of the Congress, at Calcutta in 1917, during the Home Rule agitation; Sarojini Naidu was the first Indian woman president, at Kanpur in 1925; and Nellie Sengupta presided over the Calcutta session of 1933, held in defiance of a government ban. Aruna Asaf Ali, a leader of the underground in the Quit India movement who hoisted the flag at Gowalia Tank in August 1942, did not preside over a Congress session.', explanation_hi = 'इनमें से तीन ने अध्यक्षता की। एनी बेसेंट होम रूल आंदोलन के दौरान 1917 में कलकत्ता में कांग्रेस की पहली महिला अध्यक्ष बनीं; सरोजिनी नायडू 1925 में कानपुर में पहली भारतीय महिला अध्यक्ष बनीं; और नेली सेनगुप्ता ने सरकारी प्रतिबंध के बावजूद हुए 1933 के कलकत्ता अधिवेशन की अध्यक्षता की। भारत छोड़ो आंदोलन में भूमिगत नेतृत्व करने वाली और अगस्त 1942 में गोवालिया टैंक पर झंडा फहराने वाली अरुणा आसफ़ अली ने कांग्रेस अधिवेशन की अध्यक्षता नहीं की।', concept_group_id = 'modern-women-congress-leaders', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["Annie Besant", "Sarojini Naidu", "Nellie Sengupta", "Aruna Asaf Ali"], "statements_hi": ["एनी बेसेंट", "सरोजिनी नायडू", "नेली सेनगुप्ता", "अरुणा आसफ़ अली"], "closing": "How many of the above presided over a session of the Indian National Congress before independence?", "closing_hi": "उपर्युक्त में से कितनी महिलाओं ने स्वतंत्रता से पहले भारतीय राष्ट्रीय कांग्रेस के किसी अधिवेशन की अध्यक्षता की?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-women-congress-leaders' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'hard', body = 'Consider the following statements about the Lahore Resolution of the Muslim League (March 1940):', body_hi = 'मुस्लिम लीग के लाहौर प्रस्ताव (मार्च 1940) के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The resolution, moved by Fazlul Huq at Lahore, asked that the Muslim-majority areas be grouped into ''independent states'' in which the units would be autonomous and sovereign. A convention of League legislators in 1946 changed this to a single state, and the plural was later recalled in East Pakistan''s struggle that produced Bangladesh. The press soon named it the Pakistan Resolution, though the word was not in it. Statement 3 is wrong: Iqbal spoke of a consolidated Muslim state in north-western India -- Punjab, the North-West Frontier, Sind and Baluchistan -- and did not include Bengal. The name ''Pakistan'' was coined by Choudhry Rahmat Ali in 1933.', explanation_hi = 'कथन 1 और 2 सही हैं। लाहौर में फ़ज़लुल हक़ द्वारा प्रस्तुत प्रस्ताव ने माँग की कि मुस्लिम-बहुल क्षेत्रों को ऐसे ''स्वतंत्र राज्यों'' में संगठित किया जाए जिनकी इकाइयाँ स्वायत्त और संप्रभु हों। 1946 में लीग के विधायकों के एक सम्मेलन ने इसे एक ही राज्य में बदल दिया, और बाद में बांग्लादेश बनाने वाले पूर्वी पाकिस्तान के संघर्ष में बहुवचन को याद किया गया। प्रेस ने जल्द ही इसे पाकिस्तान प्रस्ताव कहा, यद्यपि यह शब्द उसमें नहीं था। कथन 3 गलत है: इक़बाल ने उत्तर-पश्चिमी भारत, यानी पंजाब, उत्तर-पश्चिमी सीमांत, सिंध और बलूचिस्तान, के एक संगठित मुस्लिम राज्य की बात की थी, और बंगाल को शामिल नहीं किया था। ''पाकिस्तान'' नाम चौधरी रहमत अली ने 1933 में गढ़ा।', concept_group_id = 'modern-pakistan-resolution-idea', source_citation = 'Sekhar Bandyopadhyay, From Plassey to Partition and After (Orient BlackSwan)', question_data = '{"statements": ["It spoke of ''independent states'' in the plural for the Muslim-majority zones of the north-west and the east, a wording later cited in support of a separate state in eastern Bengal.", "The word ''Pakistan'' did not appear in the resolution itself.", "Muhammad Iqbal''s Allahabad address of 1930, which preceded it, had demanded a sovereign state that would include Bengal."], "statements_hi": ["इसने उत्तर-पश्चिम और पूर्व के मुस्लिम-बहुल क्षेत्रों के लिए बहुवचन में ''स्वतंत्र राज्यों'' की बात की, और इसी शब्दावली को बाद में पूर्वी बंगाल के अलग राज्य के समर्थन में उद्धृत किया गया।", "प्रस्ताव में ''पाकिस्तान'' शब्द नहीं था।", "इससे पहले के 1930 के इलाहाबाद भाषण में मुहम्मद इक़बाल ने ऐसे संप्रभु राज्य की माँग की थी जिसमें बंगाल भी शामिल हो।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-pakistan-resolution-idea' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'hard', body = 'In 1928 the Hindustan Republican Association was reorganised as the Hindustan Socialist Republican Association. Consider the following statements:', body_hi = '1928 में हिंदुस्तान रिपब्लिकन एसोसिएशन को हिंदुस्तान सोशलिस्ट रिपब्लिकन एसोसिएशन के रूप में पुनर्गठित किया गया। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. At a meeting at Feroz Shah Kotla in Delhi in September 1928, under Chandrashekhar Azad, the younger revolutionaries added ''Socialist'' to the name: they now saw freedom as including the end of exploitation of one class by another, as in Bhagat Singh''s writings and the ''Philosophy of the Bomb''. Statement 2 is wrong: its members were mostly young men of Punjab and the United Provinces -- Bhagat Singh, Sukhdev, Rajguru, Bhagwati Charan Vohra and Azad himself -- a generation after the Ghadar rising of 1915. Statement 3 is wrong on chronology: the Kakori robbery of August 1925 was the work of the HRA, founded at Kanpur in 1924; Ram Prasad Bismil, Ashfaqulla Khan, Roshan Singh and Rajendra Lahiri were hanged for it.', explanation_hi = 'केवल कथन 1 सही है। सितंबर 1928 में दिल्ली के फ़िरोज़ शाह कोटला में चंद्रशेखर आज़ाद के नेतृत्व में हुई बैठक में युवा क्रांतिकारियों ने नाम में ''सोशलिस्ट'' जोड़ा: वे अब स्वतंत्रता में एक वर्ग द्वारा दूसरे के शोषण का अंत भी शामिल मानते थे, जैसा भगत सिंह के लेखन और ''बम का दर्शन'' में दिखता है। कथन 2 गलत है: इसके सदस्य अधिकतर पंजाब और संयुक्त प्रांत के युवा थे, जैसे भगत सिंह, सुखदेव, राजगुरु, भगवती चरण वोहरा और स्वयं आज़ाद, जो 1915 के ग़दर विद्रोह के एक पीढ़ी बाद के थे। कथन 3 कालक्रम में गलत है: अगस्त 1925 की काकोरी डकैती 1924 में कानपुर में स्थापित HRA का काम थी; इसके लिए राम प्रसाद बिस्मिल, अशफ़ाक़उल्ला ख़ाँ, रोशन सिंह और राजेंद्र लाहिड़ी को फाँसी दी गई।', concept_group_id = 'modern-revolutionary-movements-hsra', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["The new name reflected the growing influence of socialist ideas and the Russian Revolution on younger revolutionaries such as Bhagat Singh.", "The HSRA drew its members mainly from Ghadar veterans who had returned from North America.", "The Kakori train robbery of 1925 was carried out by the HSRA."], "statements_hi": ["नया नाम भगत सिंह जैसे युवा क्रांतिकारियों पर समाजवादी विचारों और रूसी क्रांति के बढ़ते प्रभाव को दर्शाता था।", "HSRA के सदस्य मुख्यतः उत्तरी अमेरिका से लौटे ग़दर के पुराने क्रांतिकारी थे।", "1925 की काकोरी ट्रेन डकैती HSRA ने की थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-revolutionary-movements-hsra' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'In 1891 some leaders who opposed British rule also opposed the Age of Consent Bill, while social reformers supported it. Consider the following statements:', body_hi = '1891 में ब्रिटिश शासन का विरोध करने वाले कुछ नेताओं ने सहमति आयु विधेयक का भी विरोध किया, जबकि समाज सुधारकों ने उसका समर्थन किया। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The Act raised the age of consent for girls from 10 to 12, after the death of the child bride Phulmonee in 1890. Tilak led the opposition in the Kesari, arguing that reform must come from Hindu society itself, not from an alien state, while reformers such as Behramji Malabari and M.G. Ranade backed the Bill. Statement 3 is wrong: the early Congress kept social questions off its platform to avoid dividing its members, and they were taken up instead by the separate National Social Conference that Ranade began in 1887.', explanation_hi = 'कथन 1 और 2 सही हैं। 1890 में बाल-वधू फूलमणि की मृत्यु के बाद अधिनियम ने लड़कियों की सहमति आयु 10 से बढ़ाकर 12 कर दी। तिलक ने केसरी में विरोध का नेतृत्व करते हुए तर्क दिया कि सुधार विदेशी राज्य से नहीं, हिंदू समाज के भीतर से आना चाहिए, जबकि बहरामजी मालाबारी और एम.जी. रानाडे जैसे सुधारकों ने विधेयक का समर्थन किया। कथन 3 गलत है: प्रारंभिक कांग्रेस अपने सदस्यों में फूट से बचने के लिए सामाजिक प्रश्नों को अपने मंच से दूर रखती थी, और इन्हें रानाडे द्वारा 1887 में शुरू किए गए अलग राष्ट्रीय सामाजिक सम्मेलन ने उठाया।', concept_group_id = 'modern-age-of-consent-act-1891', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Opposition to the Bill did not always mean support for child marriage; much of it rested on the view that a foreign government should not legislate on Hindu custom.", "The episode showed that social reform and political nationalism could pull in different directions.", "The Bill became law only after the Indian National Congress endorsed it at its annual session."], "statements_hi": ["विधेयक के विरोध का अर्थ हमेशा बाल विवाह का समर्थन नहीं था; इसका बड़ा भाग इस विचार पर टिका था कि विदेशी सरकार को हिंदू प्रथा पर क़ानून नहीं बनाना चाहिए।", "इस प्रकरण ने दिखाया कि समाज सुधार और राजनीतिक राष्ट्रवाद अलग-अलग दिशाओं में खिंच सकते थे।", "कांग्रेस द्वारा अपने वार्षिक अधिवेशन में समर्थन किए जाने के बाद ही विधेयक क़ानून बना।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-age-of-consent-act-1891' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Arya Samaj:', body_hi = 'आर्य समाज के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. Dayanand held the Vedas alone to be infallible, so the practices he traced to later texts -- idol worship, ritualism, caste by birth, child marriage -- could be rejected, and widow remarriage and women''s education supported. Founded at Bombay in 1875, the Samaj found its main base in Punjab, with DAV schools and colleges and the Gurukul at Haridwar. Its shuddhi campaign of reconversion also sharpened religious rivalry. Statement 3 is wrong: Dayanand rejected the Puranas, which is why his ''Back to the Vedas'' was a call to reform.', explanation_hi = 'कथन 1 और 2 सही हैं। दयानंद केवल वेदों को अचूक मानते थे, इसलिए जिन प्रथाओं को वे बाद के ग्रंथों से जोड़ते थे, जैसे मूर्तिपूजा, कर्मकांड, जन्म आधारित जाति और बाल विवाह, उन्हें अस्वीकार किया जा सकता था, और विधवा पुनर्विवाह तथा स्त्री-शिक्षा का समर्थन किया जा सकता था। 1875 में बंबई में स्थापित समाज का मुख्य आधार पंजाब बना, जहाँ DAV विद्यालय और कॉलेज तथा हरिद्वार का गुरुकुल बने। इसके पुनर्धर्मांतरण वाले शुद्धि अभियान ने धार्मिक प्रतिद्वंद्विता को भी तीखा किया। कथन 3 गलत है: दयानंद ने पुराणों को अस्वीकार किया, इसीलिए उनका ''वेदों की ओर लौटो'' सुधार का आह्वान था।', concept_group_id = 'modern-arya-samaj-1875', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Dayanand Saraswati''s call ''Back to the Vedas'' led him to reject idol worship and caste by birth.", "Its shuddhi movement sought to bring back into the Hindu fold those who had become Muslims or Christians.", "Dayanand accepted the Puranas as being of equal authority with the Vedas."], "statements_hi": ["दयानंद सरस्वती के ''वेदों की ओर लौटो'' के आह्वान ने उन्हें मूर्तिपूजा और जन्म आधारित जाति को अस्वीकार करने की ओर ले गया।", "इसका शुद्धि आंदोलन उन लोगों को हिंदू धर्म में वापस लाना चाहता था जो मुसलमान या ईसाई बन गए थे।", "दयानंद ने पुराणों को वेदों के समान प्रामाण्य वाला माना।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-arya-samaj-1875' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'Gandhi chose the salt law as the target of civil disobedience in 1930. Consider the following statements:', body_hi = 'गांधी ने 1930 में सविनय अवज्ञा के लिए नमक क़ानून को निशाना चुना। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct, and together they explain the choice: a tax on a necessity used by every Indian, rich or poor, Hindu or Muslim, made a symbol everyone understood, and breaking the law needed only a handful of sea water. Gandhi walked about 240 miles from Sabarmati to Dandi between 12 March and 6 April 1930, and salt was made along the coasts while people inland broke other laws. Statement 3 is wrong: the salt tax brought in only a modest share of tax revenue, around 8 per cent; land revenue and customs were far larger, so the choice was political, not fiscal.', explanation_hi = 'कथन 1 और 2 सही हैं, और मिलकर चुनाव की व्याख्या करते हैं: अमीर-ग़रीब, हिंदू-मुसलमान, हर भारतीय द्वारा उपयोग की जाने वाली ज़रूरी वस्तु पर कर एक ऐसा प्रतीक बना जिसे सब समझते थे, और क़ानून तोड़ने के लिए मुट्ठी भर समुद्री पानी काफ़ी था। गांधी 12 मार्च से 6 अप्रैल 1930 के बीच साबरमती से दांडी तक लगभग 240 मील चले, और तटों पर नमक बनाया गया, जबकि भीतरी इलाकों के लोगों ने दूसरे क़ानून तोड़े। कथन 3 गलत है: नमक कर से कर राजस्व का केवल छोटा भाग, लगभग 8 प्रतिशत, आता था; भू-राजस्व और सीमा शुल्क कहीं बड़े थे, इसलिए यह चुनाव राजस्व का नहीं, राजनीति का था।', concept_group_id = 'modern-dandi-march-1930', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["Salt was used by every household, so the tax fell on the poorest as heavily as on anyone.", "Making salt was a simple act that people along the coast could perform without elaborate organisation.", "The salt tax was the largest single source of the government''s revenue."], "statements_hi": ["नमक का उपयोग हर घर करता था, इसलिए कर सबसे ग़रीब पर भी उतना ही भारी पड़ता था जितना किसी और पर।", "नमक बनाना एक सरल कार्य था जिसे तट के लोग बिना किसी विस्तृत संगठन के कर सकते थे।", "नमक कर सरकार के राजस्व का सबसे बड़ा एकल स्रोत था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-dandi-march-1930' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'Consider the following persons:', body_hi = 'निम्नलिखित व्यक्तियों पर विचार कीजिए:', explanation = 'Three were associated with the Ghadar Party, founded in 1913 on the Pacific coast of North America, with its headquarters, the Yugantar Ashram, at San Francisco. Sohan Singh Bhakna was its president; Kartar Singh Sarabha, who worked on its paper and returned to India for the planned rising of 1915, was hanged at nineteen; and Maulana Barkatullah, a founder member, later became prime minister of the Provisional Government of India set up at Kabul in 1915. Madan Lal Dhingra, who shot Curzon Wyllie in London in 1909, and V.D. Savarkar belonged to the India House circle in London, not to the Ghadar movement.', explanation_hi = 'तीन ग़दर पार्टी से जुड़े थे, जिसकी स्थापना 1913 में उत्तरी अमेरिका के प्रशांत तट पर हुई और जिसका मुख्यालय, युगांतर आश्रम, सैन फ़्रांसिस्को में था। सोहन सिंह भकना इसके अध्यक्ष थे; इसके पत्र पर काम करने वाले और 1915 के नियोजित विद्रोह के लिए भारत लौटे करतार सिंह सराभा को उन्नीस वर्ष की आयु में फाँसी दी गई; और संस्थापक सदस्य मौलाना बरकतुल्लाह बाद में 1915 में काबुल में बनी भारत की अस्थायी सरकार के प्रधानमंत्री बने। 1909 में लंदन में कर्ज़न वायली को गोली मारने वाले मदन लाल ढींगरा और वी.डी. सावरकर लंदन के इंडिया हाउस मंडल के थे, ग़दर आंदोलन के नहीं।', concept_group_id = 'modern-ghadar-komagata-maru', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["Sohan Singh Bhakna", "Kartar Singh Sarabha", "Maulana Barkatullah", "Madan Lal Dhingra", "V.D. Savarkar"], "statements_hi": ["सोहन सिंह भकना", "करतार सिंह सराभा", "मौलाना बरकतुल्लाह", "मदन लाल ढींगरा", "वी.डी. सावरकर"], "closing": "How many of the above were associated with the Ghadar Party?", "closing_hi": "उपर्युक्त में से कितने ग़दर पार्टी से जुड़े थे?", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "b", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "c", "body": "Only four", "body_hi": "केवल चार", "isCorrect": false}, {"id": "d", "body": "All five", "body_hi": "सभी पाँच", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-ghadar-komagata-maru' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'During the Quit India movement, parallel governments were set up in which of the following places?', body_hi = 'भारत छोड़ो आंदोलन के दौरान निम्नलिखित में से किन स्थानों पर समानांतर सरकारें बनाई गईं?', explanation = 'Places 1, 2 and 3 are correct. Chittu Pande set up a short-lived parallel government at Ballia in August 1942; the Tamralipta Jatiya Sarkar at Tamluk in Midnapore lasted from December 1942 to 1944; and the ''Prati Sarkar'' of Satara, under Nana Patil, lasted longest, into 1945, with its own courts. Chittagong is the trap: Surya Sen''s group proclaimed a provisional revolutionary government there in April 1930, after the armoury raid -- twelve years before Quit India. Bardoli was the scene of Vallabhbhai Patel''s no-revenue satyagraha of 1928.', explanation_hi = 'स्थान 1, 2 और 3 सही हैं। चित्तू पांडे ने अगस्त 1942 में बलिया में अल्पकालिक समानांतर सरकार बनाई; मिदनापुर के तामलुक की ताम्रलिप्त जातीय सरकार दिसंबर 1942 से 1944 तक चली; और नाना पाटिल के नेतृत्व वाली सतारा की ''प्रति सरकार'' सबसे लंबी, 1945 तक, चली, जिसकी अपनी अदालतें थीं। चटगाँव जाल है: वहाँ सूर्य सेन के दल ने अप्रैल 1930 में शस्त्रागार पर हमले के बाद एक अस्थायी क्रांतिकारी सरकार घोषित की थी, भारत छोड़ो से बारह वर्ष पहले। बारदोली वल्लभभाई पटेल के 1928 के लगान-बंदी सत्याग्रह का स्थल था।', concept_group_id = 'modern-quit-india-parallel-governments', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["Ballia", "Tamluk", "Satara", "Chittagong", "Bardoli"], "statements_hi": ["बलिया", "तामलुक", "सतारा", "चटगाँव", "बारदोली"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "1, 2 and 3 only", "body_hi": "केवल 1, 2 और 3", "isCorrect": true}, {"id": "b", "body": "1, 3 and 4 only", "body_hi": "केवल 1, 3 और 4", "isCorrect": false}, {"id": "c", "body": "2, 3 and 5 only", "body_hi": "केवल 2, 3 और 5", "isCorrect": false}, {"id": "d", "body": "1, 2, 3 and 4", "body_hi": "1, 2, 3 और 4", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-quit-india-parallel-governments' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Revolt of 1857:', body_hi = '1857 के विद्रोह के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The cartridges, believed to be greased with cow and pig fat, set off the rising at Meerut, but the annexations of the 1840s and 1850s, the dispossession of taluqdars by new revenue settlements and the sepoys'' own grievances explain why it spread. The ageing Mughal emperor gave Hindu and Muslim rebels alike a common symbol. Statement 3 is wrong: the Nizam, the Scindia (though his troops at Gwalior rebelled), the Holkar, the Rajput rulers and the Sikh chiefs of Patiala stood by the British. Canning called the princes ''breakwaters to the storm''.', explanation_hi = 'कथन 1 और 2 सही हैं। गाय और सुअर की चर्बी से चिकने माने गए कारतूसों ने मेरठ में विद्रोह भड़काया, पर 1840 और 1850 के दशकों के विलय, नए राजस्व बंदोबस्तों से तालुक़दारों की बेदख़ली और सिपाहियों की अपनी शिकायतें बताती हैं कि यह क्यों फैला। वृद्ध मुग़ल सम्राट ने हिंदू और मुसलमान विद्रोहियों को एक साझा प्रतीक दिया। कथन 3 गलत है: निज़ाम, सिंधिया (यद्यपि ग्वालियर में उनकी सेना ने विद्रोह किया), होल्कर, राजपूत शासक और पटियाला के सिख सरदार अंग्रेज़ों के साथ खड़े रहे। कैनिंग ने राजाओं को ''तूफ़ान को रोकने वाली दीवारें'' कहा।', concept_group_id = 'modern-revolt-of-1857', source_citation = 'Bipan Chandra, History of Modern India (Orient BlackSwan)', question_data = '{"statements": ["Though the greased cartridges were the immediate cause, the annexation of states and the revenue settlements had built up wider discontent.", "By proclaiming Bahadur Shah Zafar emperor, the rebels at Delhi gave the revolt a symbol of legitimacy that cut across regions and religions.", "Most of the major princes, including the Nizam of Hyderabad and the Scindia of Gwalior, joined the rebels."], "statements_hi": ["यद्यपि चर्बी वाले कारतूस तात्कालिक कारण थे, राज्यों के विलय और राजस्व बंदोबस्तों ने व्यापक असंतोष पैदा कर दिया था।", "बहादुर शाह ज़फ़र को सम्राट घोषित कर दिल्ली के विद्रोहियों ने विद्रोह को वैधता का ऐसा प्रतीक दिया जो क्षेत्रों और धर्मों से परे था।", "हैदराबाद के निज़ाम और ग्वालियर के सिंधिया सहित अधिकांश प्रमुख राजा विद्रोहियों से जुड़ गए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-revolt-of-1857' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the Swadeshi movement of 1905-08:', body_hi = '1905-08 के स्वदेशी आंदोलन के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All three are correct. Launched at the Calcutta Town Hall in August 1905, the movement brought boycott, picketing, volunteer samitis, swadeshi enterprises and national schools -- methods that the later Gandhian movements built on. The National Council of Education (1906) ran institutions such as the Bengal National College. Its weakness was its social base: the Muslim peasants of the east, many of them tenants of Hindu zamindars, were wary of a movement led by the Hindu gentry, and the government encouraged that divide. By 1908 repression and the split in the Congress had weakened it.', explanation_hi = 'तीनों कथन सही हैं। अगस्त 1905 में कलकत्ता टाउन हॉल से शुरू हुए आंदोलन ने बहिष्कार, धरना, स्वयंसेवी समितियाँ, स्वदेशी उद्यम और राष्ट्रीय विद्यालय दिए, जिन तरीक़ों पर बाद के गांधीवादी आंदोलन आगे बढ़े। राष्ट्रीय शिक्षा परिषद (1906) ने बंगाल नेशनल कॉलेज जैसी संस्थाएँ चलाईं। इसकी कमज़ोरी इसका सामाजिक आधार था: पूर्व के मुस्लिम किसान, जिनमें कई हिंदू ज़मींदारों के काश्तकार थे, हिंदू भद्रलोक के नेतृत्व वाले आंदोलन से सशंकित थे, और सरकार ने इस विभाजन को बढ़ावा दिया। 1908 तक दमन और कांग्रेस में फूट ने इसे कमज़ोर कर दिया।', concept_group_id = 'modern-swadeshi-movement-1905', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["It moved the national movement beyond petitions to mass methods such as boycott, picketing and public bonfires of foreign cloth.", "It drew limited support from the Muslim peasantry of eastern Bengal, many of whose landlords were Hindu.", "The National Council of Education set up during the movement promoted education under national rather than official control."], "statements_hi": ["इसने राष्ट्रीय आंदोलन को याचिकाओं से आगे बहिष्कार, धरना और विदेशी कपड़े की सार्वजनिक होली जैसे जन-तरीक़ों तक पहुँचाया।", "इसे पूर्वी बंगाल के मुस्लिम किसानों से सीमित समर्थन मिला, जिनके कई ज़मींदार हिंदू थे।", "आंदोलन के दौरान स्थापित राष्ट्रीय शिक्षा परिषद ने सरकारी के बजाय राष्ट्रीय नियंत्रण में शिक्षा को बढ़ावा दिया।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-swadeshi-movement-1905' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'medium', body = 'After the Non-Cooperation Movement was withdrawn, the Congress was divided between the ''pro-changers'' and the ''No-changers''. Consider the following statements:', body_hi = 'असहयोग आंदोलन वापस लिए जाने के बाद कांग्रेस ''परिवर्तन समर्थकों'' और ''अपरिवर्तनवादियों'' में बँट गई। निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. C.R. Das and Motilal Nehru formed the Swaraj Party in 1923 to contest the elections under the 1919 Act and obstruct the government from within, while No-changers such as Vallabhbhai Patel, Rajendra Prasad and C. Rajagopalachari wanted to continue khadi, national schools, Hindu-Muslim unity and work against untouchability. Statement 3 is wrong: the special Congress session at Delhi in September 1923 allowed Congressmen to contest, so the Swarajists worked as a group within the Congress; in 1925 Vithalbhai Patel became President of the Central Legislative Assembly.', explanation_hi = 'कथन 1 और 2 सही हैं। सी.आर. दास और मोतीलाल नेहरू ने 1919 के अधिनियम के तहत चुनाव लड़ने और भीतर से सरकार को बाधित करने के लिए 1923 में स्वराज पार्टी बनाई, जबकि वल्लभभाई पटेल, राजेंद्र प्रसाद और सी. राजगोपालाचारी जैसे अपरिवर्तनवादी खादी, राष्ट्रीय विद्यालय, हिंदू-मुस्लिम एकता और छुआछूत के विरुद्ध काम जारी रखना चाहते थे। कथन 3 गलत है: सितंबर 1923 में दिल्ली के विशेष कांग्रेस अधिवेशन ने कांग्रेसजनों को चुनाव लड़ने की अनुमति दी, इसलिए स्वराजवादी कांग्रेस के भीतर एक समूह के रूप में काम करते रहे; 1925 में विट्ठलभाई पटेल केंद्रीय विधान सभा के अध्यक्ष बने।', concept_group_id = 'modern-swaraj-party-1923', source_citation = 'Bipan Chandra and others, India''s Struggle for Independence (Penguin)', question_data = '{"statements": ["The pro-changers argued that entering the legislative councils would keep up political activity during the lull and expose the councils from within.", "The No-changers held that constructive work among the people would prepare them for the next mass struggle.", "The Swarajists left the Congress and contested the 1923 elections as a rival party."], "statements_hi": ["परिवर्तन समर्थकों का तर्क था कि विधान परिषदों में प्रवेश ठहराव के समय राजनीतिक गतिविधि बनाए रखेगा और परिषदों को भीतर से बेनक़ाब करेगा।", "अपरिवर्तनवादी मानते थे कि जनता के बीच रचनात्मक कार्य उसे अगले जन-संघर्ष के लिए तैयार करेगा।", "स्वराजवादियों ने कांग्रेस छोड़ दी और 1923 के चुनाव एक प्रतिद्वंद्वी दल के रूप में लड़े।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'modern-swaraj-party-1923' returning concept_group_id;
